'use strict';
// Build a RegExp from source fragments (patterns kept as data)
function logicSelOpts(cur){ return logicSelOpts(cur); }
function rx(parts, flags){ return new RegExp(parts.join(''), flags); }
var uid = function(){ var a=new Uint32Array(2); crypto.getRandomValues(a); return (a[0].toString(36)+a[1].toString(36)).slice(0,7); };

