  for (let el of c.body.querySelectorAll('[data-djid][data-djf]')){
    let ev = el.tagName==='SELECT'?'change':'input';
    el.addEventListener(ev, function(){
      var src = S.sources.find(function(s){ return s.id===el.dataset.si; });
      if (!src) return;
      var dj = (src.derivedJoins||[]).find(function(j){ return j.id===el.dataset.djid; });
      if (!dj) return;
      dj[el.dataset.djf] = el.value;
      // When table name is set, auto-load its columns from the Fusion KB
      if (el.dataset.djf === 'table' && el.value) {
        var names = fusionColNames(el.value.trim());
        if (names.length) dj.cols = names.map(function(n){ return {name:n, dataType:''}; });
      }
      // On table/alias change, rebuild each condition's Left/Right datalists in place (keeps focus)
      if (el.dataset.djf === 'table' || el.dataset.djf === 'alias') {
        var tblSrcs = derivedTableSources(src);
        var djRef = dj.alias || dj.table || '';
        for (let [dci, dc] of dj.conds||[].entries()){
          let lref = dc.lref || (tblSrcs[0] && tblSrcs[0].ref) || '';
          let rref = dc.rref || djRef || lref;
          let ls = tblSrcs.find(function(ts){ return ts.ref===lref; });
          let rs = tblSrcs.find(function(ts){ return ts.ref===rref; });
          let ldl = document.getElementById('dl-djl-'+src.id+'-'+dj.id+'-'+dci);
          let rdl = document.getElementById('dl-djr-'+src.id+'-'+dj.id+'-'+dci);
          if (ldl && ls) ldl.innerHTML = ls.cols.map(function(cn){ return '<option value="'+lref+'.'+cn+'">'; }).join('');
          if (rdl && rs) rdl.innerHTML = rs.cols.map(function(cn){ return '<option value="'+rref+'.'+cn+'">'; }).join('');
        }
      }
      refreshSQL();
    });
  }
