//  INIT
// Draggable divider to resize the Generated SQL panel (persisted per browser)
function initSqlResizer() {
  var layout = document.querySelector('.layout');
  var resizer = document.getElementById('col-resizer');
  if (!layout || !resizer) return;
  var DEFAULT_W = 420, MIN_W = 300;
  var maxW = function(){ return Math.max(MIN_W, window.innerWidth - 420); }; // keep left col usable
  var clamp = function(w){ return Math.min(maxW(), Math.max(MIN_W, w)); };
  var saved = Number.parseInt(localStorage.getItem('sqg_sqlw'), 10);
  if (saved) layout.style.setProperty('--sql-w', clamp(saved)+'px');
  var dragging = false;
  var onMove = function(e){
    if (!dragging) return;
    var x = (e.touches ? e.touches[0].clientX : e.clientX);
    var w = clamp(window.innerWidth - x);
    layout.style.setProperty('--sql-w', w+'px');
    e.preventDefault();
  };
  var onUp = function(){
    if (!dragging) return;
    dragging = false;
    resizer.classList.remove('dragging');
    document.body.style.cursor = '';
    var cur = getComputedStyle(layout).getPropertyValue('--sql-w').trim();
    if (cur) localStorage.setItem('sqg_sqlw', Number.parseInt(cur,10));
    document.removeEventListener('mousemove', onMove);
    document.removeEventListener('mouseup', onUp);
    document.removeEventListener('touchmove', onMove);
    document.removeEventListener('touchend', onUp);
  };
  var onDown = function(e){
    dragging = true;
    resizer.classList.add('dragging');
    document.body.style.cursor = 'col-resize';
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
    document.addEventListener('touchmove', onMove, {passive:false});
    document.addEventListener('touchend', onUp);
    e.preventDefault();
  };
  resizer.addEventListener('mousedown', onDown);
  resizer.addEventListener('touchstart', onDown, {passive:false});
  // Double-click resets to the default width
  resizer.addEventListener('dblclick', function(){
    layout.style.setProperty('--sql-w', DEFAULT_W+'px');
    localStorage.setItem('sqg_sqlw', DEFAULT_W);
  });
  // Re-clamp if the window is resized smaller
  window.addEventListener('resize', function(){
    var cur = Number.parseInt(getComputedStyle(layout).getPropertyValue('--sql-w'),10) || DEFAULT_W;
    layout.style.setProperty('--sql-w', clamp(cur)+'px');
  });
}

// One-click starter that wires the full ODI "enrich" nested pattern:
//   INSERT /*+APPEND*/ INTO tgt SELECT SRC_Q.* FROM ( <SRC_Q select> FROM PAA_D
//   RIGHT OUTER JOIN ( STG_1 LEFT OUTER JOIN RATES_1 ON ...) ON ... ) SRC_Q
// The FROM/joins/filters/aliases are pre-built; paste your bespoke SELECT lists into the
// three "Custom SELECT expressions" boxes (kept as inputs so columns are byte-exact).
function loadOdiEnrichPattern(){
  var rates1Select =
    "DW_FA_X_GL_RATES_D.CONVERSIONDATE AS CONVERSIONDATE ,\n" +
    "  DW_FA_X_GL_RATES_D.DAILYRATECONVERSIONRATE AS DAILYRATECONVERSIONRATE ,\n" +
    "  DW_FA_X_GL_RATES_D.FROMCURRENCY AS FROMCURRENCY ,\n" +
    "  DW_FA_X_GL_RATES_D.GLDAILYCONVERSIONTYPESUSERCONVERSIONTYPE AS GLDAILYCONVERSIONTYPESUSERCONVERSIONTYPE ,\n" +
    "  DW_FA_X_GL_RATES_D.TOCURRENCY AS TOCURRENCY";
  var pastePlaceholder = "/* PASTE this subquery's SELECT list here (columns AS aliases). */";

  var stg1 = { id:uid(), table:'DWC_ENRICH_CONSOL_OPTY_STG', alias:'DWC_ENRICH_CONSOL_OPTY_STG_1',
    schema:'FDI_EXT', isSubquery:true, colMode:'manual', cols:[], derivedCols:[],
    selectRaw:'/* PASTE the STG staging SELECT list here (e.g. DWC_ENRICH_CONSOL_OPTY_STG.OPPORTUNITY_ID AS OPPORTUNITY_ID , ... ). */',
    subWhere:[{ id:uid(), col:'DWC_ENRICH_CONSOL_OPTY_STG.W$_UPDATE_DT', op:'>=',
                val:"TO_TIMESTAMP('2026-07-03 14:52:52.84435','YYYY-MM-DD HH24:MI:SS.FF6')", logic:'AND' }] };
  var rates1 = { id:uid(), table:'DW_FA_X_GL_RATES_D', alias:'DW_FA_X_GL_RATES_D_1',
    schema:'FDI_EXT', isSubquery:true, colMode:'manual', cols:[], derivedCols:[], selectRaw:rates1Select,
    subWhere:[{ id:uid(), col:'DW_FA_X_GL_RATES_D.TOCURRENCY', op:'=', val:"'USD'", logic:'AND' },
              { id:uid(), col:'DW_FA_X_GL_RATES_D.GLDAILYCONVERSIONTYPESUSERCONVERSIONTYPE', op:'=', val:"'Hedge'", logic:'AND' }] };

  var d = newDerivedSource(1);
  d.table='DWC_ENRICH_OPTY_PAA_D'; d.schema='FDI_EXT'; d.alias='DWC_ENRICH_OPTY_PAA_D'; d.derivedAlias='SRC_Q';
  d.selectRaw = pastePlaceholder;
  d.derivedFromTables = [stg1, rates1];
  d.derivedJoins = [{ id:uid(), joinType:'RIGHT OUTER JOIN',
    conds:[{ id:uid(), l:'DWC_ENRICH_OPTY_PAA_D.OPTY_ID', op:'=', r:'DWC_ENRICH_CONSOL_OPTY_STG_1.OPPORTUNITY_ID' }],
    hasGroup:true, groupJoinType:'LEFT OUTER JOIN',
    groupConds:[{ id:uid(), l:'DWC_ENRICH_CONSOL_OPTY_STG_1.EXPECTED_CLOSE_DATE', op:'=', r:'DW_FA_X_GL_RATES_D_1.CONVERSIONDATE' },
                { id:uid(), l:'DWC_ENRICH_CONSOL_OPTY_STG_1.OPPORTUNITY_CURRENCY_CODE', op:'=', r:'DW_FA_X_GL_RATES_D_1.FROMCURRENCY' }] }];

  S.sources = [d]; S.joins = []; S.unions = []; S.mappings = [];
  S.target = { schema:'FDI_EXT', table:'DWC_ENRICH_OPTY_CF_Test' };
  S.options.appendHint = true; S.options.comment = false; S.options.selectStar = true; S.options.selectModifier = '';
  render(); refreshSQL();
  notify('Loaded ODI Enrich Pattern  paste your SELECT lists into the 3 "Custom SELECT expressions" boxes','ok');
}

function init() {
  render(); // render() now re-caches _panelEls internally
  refreshTemplateSelect();
  applyTheme();
  initSqlResizer();
  // The Live DB panel is embedded inline on the landing screen now (not gated behind a
  // click), so populate its bridge-status + saved-connections list right away.
  dbConnTab(_dbTab);
  dbConnRefreshList();
}
// Modal overlays: click-away-to-close (bound here instead of inline handlers)
document.addEventListener('click', function(ev){
  var t = ev.target;
  if (!t || !t.id) { return; }
  if (t.id === 'nl-overlay') { closeNLModal(); }
  else if (t.id === 'dbconn-overlay') { closeDbConn(); }
  else if (t.id === 'livedb-overlay') { closeLiveDB(); }
});
init();

