    var gtVal = gtM[1].replaceAll(',','');
    var gtCol = (() => { if (/price|cost/i.test(text)) { return 'PRICE'; } if (/salary|pay/i.test(text)) { return 'SALARY'; } if (/amount|spend|revenue/i.test(text)) { return 'AMOUNT'; } if (/quantity|stock/i.test(text)) { return 'QUANTITY'; } return 'AMOUNT'; })();
