    var likeTxt = containsM[1].toUpperCase();
    var containsCol = (() => { if (/product/i.test(text)) { return 'PRODUCT_NAME'; } if (/customer/i.test(text)) { return 'CUSTOMER_NAME'; } return 'NAME'; })();
