                 text.match(/\bmore\s+than\s+(\d+)\s+years?\s+old\b/i) ||
                 text.match(/\bplaced\s+over\s+(?:a\s+)?(\d+)\s+years?\s+ago\b/i);
    if (olderM) {
      var nYrs = Number.parseInt(olderM[1]);
      var orderDateCol = 'ORDER_DATE';
      out.updateWhere.push({ col:'T1.'+orderDateCol, op:'<', val:'ADD_MONTHS(SYSDATE, -'+(nYrs*12)+')' });
    }
