function nlDetect_p67(out, t){
if (/\breconcil|\bheader[\s-]?only\b|\bline[\s-]?only\b|\borphan\b|\bmatched.*unmatched\b|\bunmatched.*matched\b/.test(t)) {
    if (!out.intents.includes('RECONCILE')) out.intents.push('RECONCILE');
    if (out.joinType !== 'FULL OUTER JOIN') out.joinType = 'FULL OUTER JOIN';
  }
}
function nlDetect_p68(out, t){
if (rx([String.raw`\bdiscrep|\bmismatch|\bamount.*differ|\bnot.*balanc|\bwhere.*total.*line.*not\b|\bheader.*not.*equal.*line\b`], '').test(t)) {
    if (!out.intents.includes('DISCREPANCY')) out.intents.push('DISCREPANCY');
  }
}
function nlDetect_p69(out, t){
if (rx([String.raw`\binvoices?\s+(?:that\s+)?(?:have\s+|with\s+)?no\s+(?:matching\s+)?lines?\b|\binvoices?\s+without\s+(?:any\s+)?lines?\b|\blines?\s+without\s+(?:a\s+)?(?:matching\s+)?invoice\b|\borphan\s+lines?\b`], '').test(t)) {
    if (!out.intents.includes('ANTI_JOIN')) out.intents.push('ANTI_JOIN');
  }
}
function nlDetect_p70(out, t){
if (rx([String.raw`\bpercentage\s+of\s+(?:the\s+)?(?:invoice|total)\b|\bshare\s+of\s+(?:the\s+)?(?:invoice|total)\b|\bpct\s+of\s+invoice\b`], '').test(t)) {
    if (!out.intents.includes('NULLIF_DIVISION')) out.intents.push('NULLIF_DIVISION');
  }
}

function nlDetect(text) {
  var t  = ' ' + text.toLowerCase().replaceAll(/[^\w\s.]/g,' ') + ' ';
  var tU = t.replaceAll('_', ' ');

  var out = {
    agg:          null,   // holds fn and col
    entities:     [],     // matched NL_ENTITIES (in order of mention)
    joinPairs:    [],     // [{src, tgt, key}] explicit "join X with Y using Z"
    wantDetail:   false,
    groupByCols:  [],     // [{col, label, raw}]
    orderBy:      [],     // [{col, dir}]
    where:        [],     // [{col, op, val}]
    selCols:      [],     // explicit columns the user named
    intents:      [],     // detected intent types
    latestRecord: false,
    dedupe:       false,
    conditionals: [],
    limit:        null,
    rawText:      text,
    // New fields
    joinType:     'LEFT OUTER JOIN', // default; overridden by phrasing
    onlyLeftCols: false,             // "all columns from Table A only"
    having:       null,              // {expr} raw HAVING expression
    subquery:     null,              // holds type GT_AVG / EXISTS / NOT_EXISTS plus tbl and col
    cte:          false,             // wrap result in WITH ... AS
    cteLabel:     null,
    insertValues: [],                // [{col,val}] for INSERT intent
    updateSets:   [],                // [{col,val}] for UPDATE intent
    updateWhere:  [],                // [{col,op,val}] for UPDATE WHERE
    onClauseFilters: [],             // [{col,op,val}] filters on right-side table  goes in ON clause not WHERE
  };

  //  LIMIT 
  nlDetect_p1(out, t);

  //  INTENT: LATEST / CURRENT RECORD 
  nlDetect_p2(out, t);

  //  INTENT: DEDUPE 
  nlDetect_p3(out, t);

  //  JOIN TYPE from phrasing (trained on 188 AP join examples) 
  // Priority: explicit keyword  FULL OUTER semantic  RIGHT semantic  INNER semantic  LEFT semantic

  // 1. Explicit keywords
  nlDetect_p4(out, t);

  // 1b. CROSS JOIN semantic cues  Cartesian product / all combinations / every row  every row
  nlDetect_p5(out, t);

  // 2. FULL OUTER semantic cues
  nlDetect_p6(out, t);

  // 3. RIGHT OUTER semantic cues  focus is on preserving ALL lines (right side)
  nlDetect_p7(out, t);

  // 4. INNER JOIN semantic cues  restrict to matching records only
  nlDetect_p8(out, t);

  // 5. LEFT OUTER semantic cues  preserve ALL headers even without lines
  nlDetect_p9(out, t);

  // "only columns from Table A"  don't add right-side alias.* in SELECT
  nlDetect_p10(out, t);

  //  INTENT: INSERT 
  nlDetect_p11(out, t, text);

  //  INTENT: UPDATE 
  nlDetect_p12(out, t, text);

  //  INTENT: CTE 
  nlDetect_p13(out, t, text);

  //  INTENT: SUBQUERY 
  // "more than / greater than the average"
  nlDetect_p14(out, t);
  // "at least one X"  WHERE id IN (SELECT DISTINCT...)
  nlDetect_p15(out, t);
  // "never been X" / "have never been X"  NOT IN subquery or LEFT JOIN IS NULL
  nlDetect_p16(out, t);

  //  LIKE filters 
  var likeStartM = text.match(/\bstarts?\s+with\s+(?:the\s+(?:letter\s+))?['"]?([a-z0-9%_]+)['"]?/i);
  var likeEndM   = text.match(/\bends?\s+with\s+['"]?([a-z0-9%_]+)['"]?/i);
  var likeContM  = text.match(/\bcontains?\s+['"]?([a-z0-9%_]+)['"]?/i);
  var likeCol = null, likeVal = null;
  if (likeStartM || likeEndM || likeContM) {
    // detect column
    for (let ec of NL_EXPLICIT_COLS){
      if (!likeCol && nlHasPhrase(t, tU, ec.words)) likeCol = ec.col;
    }
    if (!likeCol) likeCol = 'NAME';
    if (likeStartM) likeVal = "'"+likeStartM[1].toUpperCase()+"%'";
    else if (likeEndM) likeVal = "'%"+likeEndM[1].toUpperCase()+"'";
    else likeVal = "'%"+likeContM[1].toUpperCase()+"%'";
    out.where.push({ col:'T1.'+likeCol, op:'LIKE', val:likeVal });
    if (!out.intents.includes('FILTER')) out.intents.push('FILTER');
  }

  //  IS NULL / IS NOT NULL from phrasing 
  // "do not have a manager" / "no X assigned" / "without a X"
  var nullPhrases = [
    { re:rx([String.raw`\bno\s+manager\b|\bwithout\s+a?\s+manager\b|\bdo\s+not\s+have\s+a\s+manager\b`], ''), col:'MANAGER_ID', op:'IS NULL' },
    { re:rx([String.raw`\bno\s+department\b|\bwithout\s+a?\s+department\b`], ''), col:'DEPARTMENT_ID', op:'IS NULL' },
    { re:/\bno\s+email\b|\bwithout\s+(?:an?\s+)?email\b/, col:'EMAIL_ADDRESS', op:'IS NULL' },
  ];
  for (let np of nullPhrases){
    if (np.re.test(t) && !out.where.some(function(w){ return w.col==='T1.'+np.col; })) {
      out.where.push({ col:'T1.'+np.col, op:np.op, val:'' });
      if (!out.intents.includes('FILTER')) out.intents.push('FILTER');
    }
  }

  //  HAVING 
  // "where total/sum/avg > N" after GROUP BY context, or explicit HAVING keyword
  var havRe = rx([String.raw`\bhaving\s+(.+?)(?:\s*$|;)`], 'i');
  var havM2 = text.match(havRe);
  if (!havM2) {
    // "where total salary is greater than 500000" / "average is above 200"
    havM2 = text.match(/\bwhere\s+(?:the\s+)?(?:total|sum|average|avg|count)\b.{0,40}(?:greater than|more than|above|over|>)\s*([\d,]+)/i) ||
            text.match(/\b(?:total|sum|average|avg)\s+.{0,20}(?:greater than|more than|above|over|>)\s*([\d,]+)/i);
  }
  nlDetect_p17(havM2, out, text);

  //  ORDER BY column detection 
  // "by price", "by amount", "by date", "by salary", "by name", "by region"
  var orderColRe = rx([String.raw`\b(?:order(?:ed)?\s+by|sort(?:ed)?\s+by|rank(?:ed)?\s+by)\s+([\w\s]+?)(?:\s+(?:from|asc|desc|highest|lowest|$))`], 'i');
  nlDetect_p18(orderColRe, out, t, text);

  //  INTENT: CONDITIONAL (if null treat as) 
  var condM = text.match(rx([String.raw`\bif\s+(\w[\w\s]*?)\s+is\s+null\s+(?:then\s+)?(?:treat\s+(?:it\s+)?as\s+|use\s+)?['"]?(\w+)['"]?`], 'gi'));
  if (!condM) condM = text.match(/\btreat\s+null\s+(?:as|like)\s+['"]?(\w+)['"]?/gi);
  nlDetect_p19(condM, out, text);

  //  AGGREGATE 
  for (let a of NL_AGG){
    for (let w of a.words){
      if (nlHasPhrase(t, tU, [w])) {
        if (!out.agg) { out.agg = { fn:a.fn, col:null }; out.intents.push('AGGREGATE'); }
      }
    }
  }

  //  AGGREGATE COLUMN 
  if (out.agg) {
    // Check explicit cols first (most specific)
    for (let ec of NL_EXPLICIT_COLS){
      if (!out.agg.col && nlHasPhrase(t, tU, ec.words)) out.agg.col = ec.col;
      if (!out.agg.col && (t.includes(' '+ec.col.toLowerCase()+' ') || tU.includes(' '+ec.col.toLowerCase().replaceAll('_',' ')+' '))) out.agg.col = ec.col;
    }
    // Fall back to numeric col hints
    if (!out.agg.col) {
      for (let h of NL_COL_HINTS.filter(function(h){ return h.num; })){
        if (!out.agg.col && nlHasPhrase(t, tU, h.words)) out.agg.col = h.col;
      }
    }
  }

  //  ENTITIES (longest phrase first so multi-word beats single-word) 
  var sorted = NL_ENTITIES.slice().sort(function(a,b){
    return Math.max.apply(null,b.words.map(function(w){return w.length;})) -
           Math.max.apply(null,a.words.map(function(w){return w.length;}));
  });
  for (let e of sorted){
    if (nlHasPhrase(t, tU, e.words) && !out.entities.some(function(x){ return x.tables[0]===e.tables[0]; })) {
      out.entities.push(e);
    }
  }

  // Direct Oracle table name scan (e.g. "AP_Invoice_all" typed literally)
  nlDetect_p20(out, t, tU);

  //  EXPLICIT JOIN PATTERN: "join X with Y using Z" 
  // Matches: "join A with/to/and B using/on/by Z"
  var joinRe = rx([String.raw`\bjoin\s+([\w\s]+?)\s+(?:with|to|and)\s+([\w\s]+?)(?:\s+(?:using|on|by|via|based on)\s+([\w\s]+?))?(?:\s*$|,|\band\b|\bwhere\b|\bfilter\b|\bshow\b)`], 'gi');
  var jm;
  while ((jm = joinRe.exec(text)) !== null) {
    out.intents.push('JOIN');
    var srcPhrase = jm[1].trim().toLowerCase();
    var tgtPhrase = jm[2].trim().toLowerCase();
    var keyPhrase = jm[3] ? jm[3].trim().toLowerCase() : null;
    var srcEnt = null, tgtEnt = null;
    for (let e of NL_ENTITIES){
      if (!srcEnt && nlHasPhrase(' '+srcPhrase+' ', ' '+srcPhrase.replaceAll('_',' ')+' ', e.words)) srcEnt = e;
      if (!tgtEnt && nlHasPhrase(' '+tgtPhrase+' ', ' '+tgtPhrase.replaceAll('_',' ')+' ', e.words)) tgtEnt = e;
    }
    if (srcEnt && !out.entities.some(function(x){ return x.tables[0]===srcEnt.tables[0]; })) out.entities.push(srcEnt);
    if (tgtEnt && !out.entities.some(function(x){ return x.tables[0]===tgtEnt.tables[0]; })) out.entities.push(tgtEnt);
    var resolvedKey = nlResolveJoinKey(keyPhrase, srcEnt, tgtEnt);
    if (srcEnt && tgtEnt) out.joinPairs.push({ src:srcEnt, tgt:tgtEnt, key:resolvedKey });
  }

  //  WANT DETAIL 
  nlDetect_p21(out, t);

  //  GROUP BY hints 
  nlDetect_p22(out, t, tU);

  //  STATUS / CONDITION filters (NL_STATUS_MAPS) 
  nlDetect_p23(out, t, tU);

  //  DATE filters 
  nlDetect_p24(out, t, tU);

  //  NUMERIC comparison (greater than, less than, between) 
  for (let p of NL_COND_OPS){
    let m = text.match(p.re);
    if (!m) continue;
    let rawVal = (m[1]||'').trim().replaceAll(',','');
    let numVal = Number.parseFloat(rawVal);
    let val = Number.isNaN(numVal) ? "'"+rawVal.toUpperCase()+"'" : rawVal;
    if (p.op==='LIKE') val = "'%"+rawVal.toUpperCase()+"%'";
    let col = null;
    let textL = text.toLowerCase(), textLU = textL.replaceAll('_',' ');
    for (let ec of NL_EXPLICIT_COLS){
      if (!col) {
        for (let w of ec.words){ if (textL.includes(w) || textLU.includes(w.replaceAll('_',' '))) col = ec.col; }
        if (textL.includes(ec.col.toLowerCase())) col = ec.col;
      }
    }
    if (!col) { for (let h of NL_COL_HINTS){
      if (!col) { for (let w of h.words){ if (textL.includes(w)) col = h.col; } }
    } }
    if (!col && out.entities.length && out.entities[0].numCol) col = out.entities[0].numCol;
    if (!col) col = 'AMOUNT';
    out.where.push({ col:'T1.'+col, op:p.op, val:val });
    if (!out.intents.includes('FILTER')) out.intents.push('FILTER');
  }

  // BETWEEN N and M pattern
  var betM = text.match(/\bbetween\s+([0-9,.]+)\s+and\s+([0-9,.]+)/i);
  if (betM) {
    var bcol = null;
    var textL2 = text.toLowerCase();
    for (let ec of NL_EXPLICIT_COLS){ if (!bcol && ec.words.some(function(w){ return textL2.includes(w); })) bcol = ec.col; }
    if (!bcol && out.entities.length && out.entities[0].numCol) bcol = out.entities[0].numCol;
    if (!bcol) bcol = 'AMOUNT';
    out.where.push({ col:'T1.'+bcol+' BETWEEN '+betM[1].replaceAll(',','')+' AND '+betM[2].replaceAll(',',''), op:'', val:'' });
  }

  //  STATUS = X / TYPE = Y freeform 
  nlDetect_p25(out, text);

  //  EXPLICIT COLUMNS in SELECT 
  for (let ec of NL_EXPLICIT_COLS){
    if (nlHasPhrase(t, tU, ec.words)) {
      if (out.agg && out.agg.col === ec.col) continue;
      if (!out.selCols.includes(ec.col)) out.selCols.push(ec.col);
    }
  }
  // Scan actual table columns for names the user typed with underscores
  nlDetect_p26(out, t, tU);

  //  ORDER BY 
  nlDetect_p27(out, t);
  nlDetect_p28(out, t);
  nlDetect_p29(out, t);

  //  NOT EQUAL ( <> ) phrasing 
  // "not from IT" / "outside the IT department" / "not in IT department" / "do not belong to IT"
  nlDetect_p30(out, text);
  // "not equal to X" / "does not equal X"
  nlDetect_p31(out, text);

  //  NOT IN multi-value 
  // "neither X nor Y" / "not from X or Y" / "excluding those from X and Y"
  nlDetect_p32(out, text);

  //  YEAR filter: "in [year]" / "from 2023" / "during 2023" 
  nlDetect_p33(out, text);

  //  "LAST N DAYS"  SYSDATE - N (Oracle) 
  nlDetect_p34(out, text);

  //  COUNT DISTINCT 
  if (/\bdistinct\b|\bunique\b/.test(t) && out.agg && out.agg.fn === 'COUNT') {
    out.agg.distinct = true;
  }
  nlDetect_p35(out, t);

  //  MEDIAN 
  nlDetect_p36(out, t);

  //  HAVING BETWEEN (range) 
  nlDetect_p37(out, text);

  //  IS NOT NULL from "have a X" / "with a X" / "provided a X" phrasing 
  var notNullPhrases = [
    { re:rx([String.raw`\bhave\s+a\s+(?:phone|phone\s+number|telephone)\b|\bphone\s+(?:number\s+)?is\s+not\s+null\b|\bwith\s+a\s+phone\b`], ''), col:'PHONE_NUMBER' },
    { re:rx([String.raw`\bhave\s+(?:an?\s+)?email\b|\bwith\s+an?\s+email\b|\bemail\s+is\s+not\s+null\b`], ''), col:'EMAIL_ADDRESS' },
    { re:/\bhave\s+a\s+manager\b|\bwith\s+a\s+manager\b|\bmanager\s+is\s+not\s+null\b/, col:'MANAGER_ID' },
  ];
  for (let np of notNullPhrases){
    if (np.re.test(t) && !out.where.some(function(w){ return w.col==='T1.'+np.col; })) {
      out.where.push({ col:'T1.'+np.col, op:'IS NOT NULL', val:'' });
      if (!out.intents.includes('FILTER')) out.intents.push('FILTER');
    }
  }

  //  UPDATE: percentage raise patterns 
  // "increase salary by N percent" / "raise salaries by N percent" / "give a N percent raise"
  nlDetect_p38(out, text);

  //  ANTI-JOIN: "never placed / never been sold / not assigned to any" 
  //  LEFT JOIN + WHERE right.key IS NULL (preferred over NOT IN subquery)
  nlDetect_p39(out, t);

  //  CROSS JOIN: "all combinations" / "every X with every Y" / "pair every" 
  nlDetect_p40(out, t);

  //  UNION / UNION ALL 
  nlDetect_p41(out, t);

  //  SELF JOIN: "each X and their manager" / "pairs of X in the same Y" 
  nlDetect_p42(out, t);

  //  EXISTS / NOT EXISTS (correlated WHERE clause) 
  nlDetect_p43(out, t);
  nlDetect_p44(out, t);

  //  RIGHT OUTER JOIN: "all [right table] even if no [left table] belongs" 
  nlDetect_p45(out, t);

  //  LAG / LEAD window functions 
  nlDetect_p46(out, t);
  nlDetect_p47(out, t);

  //  NTILE (divide into N groups / quartile) 
  var ntileM = text.match(/\bdivide\s+(?:all\s+)?\w+\s+into\s+(\d+)\s+(?:equal\s+)?(?:groups?|buckets?|parts?)\b/i) ||
               text.match(/\b(4)\s+equal\s+groups?\b/i);
  nlDetect_p48(ntileM, out, t);

  //  COALESCE / null substitution: "using 'X' if no Y" / "show 'X' if not assigned" 
  nlDetect_p49(out, text);

  //  CASE WHEN tiers: "label them X if..., Y if..., otherwise Z" 
  nlDetect_p50(out, t);

  //  RUNNING TOTAL: "running total" / "cumulative sum" / "running sum" 
  nlDetect_p51(out, t);

  //  PIVOT: "by quarter in a single row" / "pivot" 
  if (/\bby\s+quarter\s+in\s+a\s+single\s+row\b|\bpivot\b|\bcross\s*tab\b/i.test(t)) {
    out.intents.push('PIVOT');
  }

  //  DELETE intent 
  nlDetect_p52(out, t, text);

  //  LESS-THAN filter: "cheaper than N", "price under N", "below N", "less than N", "lower than N" 
  var ltM = text.match(rx([String.raw`\b(?:cheaper\s+than|priced?\s+(?:under|below)|costs?\s+less\s+than|price\s+(?:lower|less)\s+than|under|below)\s+(\d[\d,]*(?:\.\d+)?)\b`], 'i')) ||
            text.match(rx([String.raw`\b(?:less\s+than|lower\s+than|fewer\s+than)\s+(\d[\d,]*(?:\.\d+)?)(?:\s+(?:dollars?|units?|items?))?\b`], 'i'));
  nlDetect_p53(ltM, out, text);

  //  GREATER-THAN filter: "more than N", "greater than N", "above N", "over N", "exceeds N", "higher than N" 
  nlDetect_p54(out, text);

  //  BOOLEAN/BIT filter: "active/inactive employees", "is active", "is deleted" 
  nlDetect_p55(out, t);
  nlDetect_p56(out, t);

  //  SUFFIX LIKE: "email ends with X.com", "name ends in X" 
  nlDetect_p57(out, text);

  //  CONTAINS LIKE: "name contains X", "name includes X", "X in their name" 
  nlDetect_p58(out, text);

  //  PREFIX LIKE: "name starts with A", "name begins with A" 
  nlDetect_p59(out, text);

  //  STDEV / STDDEV aggregate 
  nlDetect_p60(out, t);

  //  RANK / DENSE_RANK intents 
  nlDetect_p61(out, t);

  //  ROW_NUMBER as primary intent 
  nlDetect_p62(out, t);

  //  MERGE (Oracle MERGE INTO...USING...WHEN MATCHED/NOT MATCHED) 
  nlDetect_p63(out, t, text);

  //  UPDATE: orders older than N years (Oracle: ADD_MONTHS) 
  nlDetect_p64(out, text);

  //  Multi-column ORDER BY: "by X then by Y descending" 
  nlDetect_p65(out, text);

  //  AP: LINE TYPE filter  ON clause (not WHERE) for LEFT/RIGHT JOIN 
  // e.g. "only ITEM type lines", "lines of type TAX", "filter to FREIGHT lines but keep all invoices"
  nlDetect_p66(out, t);

  //  RECONCILE intent: FULL OUTER JOIN + reconciliation status 
  nlDetect_p67(out, t);

  //  DISCREPANCY intent: invoice amount vs sum of lines 
  nlDetect_p68(out, t);

  //  AP: "invoices without any lines" / "orphan lines"  ANTI_JOIN 
  nlDetect_p69(out, t);

  //  AP NULLIF division: percentage of invoice / share of total 
  nlDetect_p70(out, t);

  return out;
}

// --- helpers extracted from nlBuildSQL (behavior-identical) ---
function nlBuildSQL_p1(mainEnt, parsed){
if (parsed.agg && !parsed.agg.col) {
    parsed.agg.col = (parsed.agg.fn === 'COUNT' && !parsed.agg.distinct) ? '*' : (mainEnt.numCol || 'AMOUNT');
  }
}
function nlBuildSQL_p2(FUSION_ALIAS_MAP, joins, mainEnt, mainTbl, parsed, usedTables){
if (parsed.wantDetail && mainEnt.detailJoin && !usedTables.includes(mainEnt.detailJoin)) {
    var dAlias = FUSION_ALIAS_MAP[mainEnt.detailJoin] || ('T'+(joins.length+2));
    var dSugg  = fusionJoinSuggest(mainTbl, mainEnt.detailJoin);
    var dlk = dSugg.length ? dSugg[0].lc : (mainEnt.joinKey||'ID');
    var drk = dSugg.length ? dSugg[0].rc : (mainEnt.joinKey||'ID');
    joins.push({ tbl:mainEnt.detailJoin, alias:dAlias, lkey:dlk, rkey:drk, type:parsed.joinType||'LEFT OUTER JOIN' });
  }
}
function nlBuildSQL_p3(joins, mainEnt, mainTbl, parsed){
if (parsed.intents.includes('SELF_JOIN') && !joins.some(function(j){ return j.tbl===mainTbl && j.alias==='M'; })) {
    var selfKey = mainEnt.joinKey || 'EMPLOYEE_ID';
    joins.push({ tbl:mainTbl, alias:'M', lkey:'MANAGER_ID', rkey:selfKey, type:'LEFT OUTER JOIN' });
  }
}
function nlBuildSQL_p4(alias, mainEnt, parsed, windowSelParts){
if (parsed.intents.includes('LAG')) {
    var lagCol = (mainEnt.numCol || 'AMOUNT');
    var lagPartKey = mainEnt.joinKey || 'CUSTOMER_ID';
    var lagDateCol = mainEnt.dateCol || 'ORDER_DATE';
    windowSelParts.push('LAG('+alias+'.'+lagCol+', 1) OVER (PARTITION BY '+alias+'.'+lagPartKey+
                        ' ORDER BY '+alias+'.'+lagDateCol+') AS PREVIOUS_'+lagCol);
  }
}
function nlBuildSQL_p5(alias, mainEnt, parsed, windowSelParts){
if (parsed.intents.includes('LEAD')) {
    var leadCol = (mainEnt.numCol || 'AMOUNT');
    var leadPartKey = mainEnt.joinKey || 'CUSTOMER_ID';
    var leadDateCol = mainEnt.dateCol || 'ORDER_DATE';
    windowSelParts.push('LEAD('+alias+'.'+leadCol+', 1) OVER (PARTITION BY '+alias+'.'+leadPartKey+
                        ' ORDER BY '+alias+'.'+leadDateCol+') AS NEXT_'+leadCol);
  }
}
function nlBuildSQL_p6(alias, mainEnt, parsed, windowSelParts){
if (parsed.intents.includes('NTILE')) {
    var nbuckets = parsed.ntileBuckets || 4;
    var ntileOrderCol = (mainEnt.numCol || 'SALARY');
    windowSelParts.push('NTILE('+nbuckets+') OVER (ORDER BY '+alias+'.'+ntileOrderCol+' DESC) AS QUARTILE');
  }
}
function nlBuildSQL_p7(alias, mainEnt, parsed, windowSelParts){
if (parsed.intents.includes('RUNNING_TOTAL')) {
    var rtCol = (mainEnt.numCol || 'AMOUNT');
    var rtPartKey = mainEnt.joinKey || 'CUSTOMER_ID';
    var rtDateCol = mainEnt.dateCol || 'ORDER_DATE';
    windowSelParts.push('SUM('+alias+'.'+rtCol+') OVER (PARTITION BY '+alias+'.'+rtPartKey+
                        ' ORDER BY '+alias+'.'+rtDateCol+
                        ' ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS RUNNING_TOTAL');
  }
}
function nlBuildSQL_p8(alias, mainEnt, parsed, windowSelParts){
if (parsed.intents.includes('PIVOT')) {
    var pvCol = (mainEnt.numCol || 'AMOUNT');
    windowSelParts.push("SUM(CASE WHEN TO_CHAR("+alias+".ORDER_DATE,'Q') = '1' THEN "+alias+"."+pvCol+" END) AS Q1_TOTAL",
                        "SUM(CASE WHEN TO_CHAR("+alias+".ORDER_DATE,'Q') = '2' THEN "+alias+"."+pvCol+" END) AS Q2_TOTAL",
                        "SUM(CASE WHEN TO_CHAR("+alias+".ORDER_DATE,'Q') = '3' THEN "+alias+"."+pvCol+" END) AS Q3_TOTAL",
                        "SUM(CASE WHEN TO_CHAR("+alias+".ORDER_DATE,'Q') = '4' THEN "+alias+"."+pvCol+" END) AS Q4_TOTAL");
  }
}
function nlBuildSQL_p9(alias, mainEnt, parsed, windowSelParts){
if (parsed.intents.includes('CASE_WHEN_TIERS')) {
    var tierCol = (mainEnt.numCol || 'SALARY');
    windowSelParts.push("CASE WHEN "+alias+"."+tierCol+" >= 100000 THEN 'Senior'\n"+
                        "          WHEN "+alias+"."+tierCol+" >= 60000 THEN 'Mid'\n"+
                        "          ELSE 'Junior' END AS LEVEL_TIER");
  }
}
function nlBuildSQL_p10(joins, parsed, windowSelParts){
if (parsed.intents.includes('COALESCE') && parsed.coalesceDefault && joins.length) {
    var cjAlias = joins[0].alias;
    var cjCol = parsed.entities[1] ? (parsed.entities[1].numCol || 'CATEGORY') : 'CATEGORY';
    windowSelParts.push("COALESCE("+cjAlias+"."+cjCol+", '"+parsed.coalesceDefault+"') AS "+cjCol);
  }
}
function nlBuildSQL_p11(joins, parsed, windowSelParts){
if (parsed.intents.includes('SELF_JOIN') && joins.some(function(j){ return j.alias==='M'; })) {
    windowSelParts.push("M.FIRST_NAME || ' ' || M.LAST_NAME AS MANAGER_NAME");
  }
}
function nlBuildSQL_p12(alias, joins, mainEnt, parsed, windowSelParts){
if (parsed.intents.includes('NULLIF_DIVISION') && joins.length) {
    var nlJAlias = joins[0].alias;
    var nlRCol   = (joins[0].tbl==='AP_INVOICE_LINES_ALL') ? 'AMOUNT' : (NL_ENTITIES.find(function(e){ return e.tables[0]===joins[0].tbl; })||{}).numCol || 'AMOUNT';
    var nlLCol   = mainEnt.numCol || 'INVOICE_AMOUNT';
    windowSelParts.push('ROUND(100.0 * '+nlJAlias+'.'+nlRCol+' / NULLIF('+alias+'.'+nlLCol+', 0), 2) AS LINE_PCT_OF_INVOICE');
  }
}
function nlBuildSQL_p13(alias, mainEnt, parsed, whereParts){
if (parsed.intents.includes('EXISTS') && !parsed.subquery) {
    var exTbl = parsed.entities[1] ? parsed.entities[1].tables[0] : 'ORDERS';
    var exKey = mainEnt.joinKey || 'CUSTOMER_ID';
    whereParts.push((whereParts.length?'AND    ':'')+
      'EXISTS (\n         SELECT 1\n         FROM   '+exTbl+' EX\n         WHERE  EX.'+exKey+' = '+alias+'.'+exKey+'\n       )');
  }
}
function nlBuildSQL_p14(alias, mainEnt, parsed, whereParts){
if (parsed.intents.includes('NOT_EXISTS') && !parsed.subquery) {
    var nexTbl = parsed.entities[1] ? parsed.entities[1].tables[0] : 'ORDERS';
    var nexKey = mainEnt.joinKey || 'CUSTOMER_ID';
    whereParts.push((whereParts.length?'AND    ':'')+
      'NOT EXISTS (\n         SELECT 1\n         FROM   '+nexTbl+' NEX\n         WHERE  NEX.'+nexKey+' = '+alias+'.'+nexKey+'\n       )');
  }
}
function nlBuildSQL_p15(alias, mainEnt, mainTbl, parsed, whereParts){
if (parsed.subquery) {
    var sq = parsed.subquery;
    var sqTbl  = mainTbl;
    var sqCol  = (parsed.agg && parsed.agg.col && parsed.agg.col!=='*') ? parsed.agg.col
               : (mainEnt.numCol || 'AMOUNT');
    var sqKey  = mainEnt.joinKey || 'ID';
    if (sq.type === 'GT_AVG') {
      var sqFn = (parsed.agg && parsed.agg.fn) || 'AVG';
      whereParts.push((whereParts.length?'AND    ':'')+alias+'.'+sqCol+' > (SELECT '+sqFn+'('+sqCol+') FROM '+sqTbl+')');
    } else if (sq.type === 'EXISTS') {
      var sqDetail = sq.detail ? sq.detail.toUpperCase().replaceAll(/\s+/g,'_') : 'ORDERS';
      whereParts.push((whereParts.length?'AND    ':'')+alias+'.'+sqKey+' IN (\n         SELECT DISTINCT '+sqKey+' FROM '+sqDetail+'\n       )');
    } else if (sq.type === 'NOT_EXISTS') {
      var sqDetail2 = parsed.entities[1] ? parsed.entities[1].tables[0] : 'ORDER_DETAILS';
      whereParts.push((whereParts.length?'AND    ':'')+alias+'.'+sqKey+' NOT IN (\n         SELECT DISTINCT '+sqKey+' FROM '+sqDetail2+'\n       )');
    }
  }
}

function nlBuildSQL(parsed) {
  // Fallback: use loaded source if no entity detected
  if (!parsed.entities.length) {
    if (S.sources.length && S.sources[0].table) {
      parsed.entities = [{ tables:[S.sources[0].table], cat:'USER',
        numCol: (S.sources[0].columns.find(function(c){return c.dataType==='NUMBER';})||{name:null}).name,
        joinKey:'ID' }];
    } else {
      return '-- Could not identify a table from your description.\n'+
             '-- Try: "Join employees with assignments using person id"\n'+
             '-- Or:  "Show invoice amount by supplier for last 6 months"';
    }
  }

  var mainEnt = parsed.entities[0];
  var mainTbl = mainEnt.tables[0];

  // Oracle Fusion module-specific alias map (canonical aliases used in AP/GL/PO training data)
  var FUSION_ALIAS_MAP = {
    'AP_INVOICES_ALL':'AI',           'AP_INVOICE_LINES_ALL':'AIL',
    'AP_INVOICE_DISTRIBUTIONS_ALL':'AID', 'AP_CHECKS_ALL':'ACK',
    'POZ_SUPPLIERS':'PS',             'POZ_SUPPLIER_SITES_ALL_M':'PSS',
    'GL_JE_HEADERS':'GJH',            'GL_JE_LINES':'GJL',
    'GL_BALANCES':'GLB',              'GL_LEDGERS':'GLL',
    'GL_CODE_COMBINATIONS':'GCC',
    'PO_HEADERS_ALL':'POH',           'PO_LINES_ALL':'POL',
    'PO_REQUISITION_HEADERS_ALL':'PRH', 'RCV_SHIPMENT_HEADERS':'RSH',
    'PER_ALL_PEOPLE_F':'PAP',         'PER_ALL_ASSIGNMENTS_M':'PAA',
    'HR_DEPARTMENTS_VL':'HD',
    'PA_PROJECTS_ALL':'PPA',          'PA_TASKS':'PAT',
    'AR_PAYMENT_SCHEDULES_ALL':'ARP', 'HZ_PARTIES':'HZP', 'HZ_CUST_ACCOUNTS':'HZC',
    'MTL_SYSTEM_ITEMS_B':'MSI',       'MTL_ONHAND_QUANTITIES_DETAIL':'MOQ',
  };

  var alias = FUSION_ALIAS_MAP[mainTbl] || 'T1';

  // Resolve aggregate column
  nlBuildSQL_p1(mainEnt, parsed);

  //  BUILD JOINS 
  // Collect all additional entities (from join pattern or multi-entity detection)
  var joins = [];
  var usedTables = [mainTbl];

  //  INSERT intent  early return 
  if (parsed.intents.includes('INSERT')) {
    var ins = parsed.insertValues;
    var insCols = ins.length ? ins.map(function(v){ return v.col; }).join(', ') : '/* col1, col2 */';
    var insVals = ins.length ? ins.map(function(v){ return v.val; }).join(', ') : '/* val1, val2 */';
    return '-- "'+parsed.rawText+'"\nINSERT INTO '+mainTbl+' ('+insCols+')\nVALUES ('+insVals+');\n';
  }

  //  UPDATE intent  early return 
  if (parsed.intents.includes('UPDATE')) {
    var upLines = ['-- "'+parsed.rawText+'"', 'UPDATE '+mainTbl];
    var sets = parsed.updateSets;
    if (sets.length) {
      upLines.push('SET '+sets.map(function(s,i){
        return (i>0?'    ':'')+s.col+' = '+(s.expr || s.val || '/* value */');
      }).join(',\n'));
    } else {
      upLines.push('SET /* column = value */');
    }
    var uw = parsed.updateWhere;
    if (uw.length) {
      upLines.push('WHERE '+uw.map(function(w,i){
        return (i>0?'  AND ':'')+w.col+' '+w.op+' '+w.val;
      }).join('\n'));
    } else if (parsed.where.length) {
      upLines.push('WHERE '+parsed.where.map(function(w,i){
        var noVal = ['IS NULL','IS NOT NULL'].includes(w.op)||w.op==='';
        return (i>0?'  AND ':'')+w.col+(w.op?' '+w.op:'')+(noVal?'':' '+w.val);
      }).join('\n'));
    }
    upLines.push(';');
    return upLines.join('\n');
  }

  //  MERGE intent  early return 
  if (parsed.intents.includes('MERGE')) {
    var mSrc    = parsed.mergeSource || ('Staging' + mainTbl);
    var mKey    = mainEnt.joinKey || 'ID';
    var mLines  = [
      '-- "'+parsed.rawText+'"',
      '-- Intent: MERGE (Oracle MERGE INTO)',
      'MERGE INTO '+mainTbl+' TGT',
      'USING '+mSrc+' SRC',
      '    ON (TGT.'+mKey+' = SRC.'+mKey+')',
      'WHEN MATCHED THEN',
      '    UPDATE SET',
      '        TGT./* col1 */ = SRC./* col1 */,',
      '        TGT./* col2 */ = SRC./* col2 */',
      'WHEN NOT MATCHED THEN',
      '    INSERT ('+mKey+', /* col1 */, /* col2 */)',
      '    VALUES (SRC.'+mKey+', SRC./* col1 */, SRC./* col2 */)',
    ];
    // If "delete" or "full sync" is also mentioned add WHEN NOT MATCHED BY SOURCE
    if (/\bdelete\b|\bfull\s+sync\b|\bnot\s+(?:in|exist)\s+in\s+(?:the\s+)?source\b/i.test(parsed.rawText)) {
      mLines.push('WHEN NOT MATCHED BY SOURCE THEN',
                  '    DELETE');
    }
    mLines.push(';');
    return mLines.join('\n');
  }

  //  RANK / DENSE_RANK / ROW_NUMBER  early return 
  if (parsed.intents.includes('RANK') || parsed.intents.includes('DENSE_RANK') || parsed.intents.includes('ROW_NUMBER')) {
    var rankFn  = (() => { if (parsed.intents.includes('DENSE_RANK')) { return 'DENSE_RANK()'; } if (parsed.intents.includes('RANK')) { return 'RANK()'; } return 'ROW_NUMBER()'; })();
    var rankCol = mainEnt.numCol || 'SALARY';
    var rankPartCol = mainEnt.joinKey || 'DEPARTMENT_ID';
    // Determine if PARTITION BY applies
    var hasPart = /\bper\s+(?:department|customer|category|group)\b|\bwithin\s+each\b|\bpartition\b/i.test(parsed.rawText);
    var partClause = hasPart ? 'PARTITION BY '+alias+'.'+rankPartCol+' ' : '';
    var rankAlias = (() => { if (parsed.intents.includes('DENSE_RANK')) { return 'DENSE_RANK_NUM'; } if (parsed.intents.includes('RANK')) { return 'SALARY_RANK'; } return 'ROW_NUM'; })();
    var rankLines = [
      '-- "'+parsed.rawText+'"',
      '-- Intent: '+parsed.intents.filter(function(i){ return ['RANK','DENSE_RANK','ROW_NUMBER'].includes(i); }).join(', '),
      'SELECT '+alias+'.*,',
      '       '+rankFn+' OVER ('+partClause+'ORDER BY '+alias+'.'+rankCol+' DESC) AS '+rankAlias,
      'FROM   '+fromClause,
    ];
    if (parsed.where.length) {
      rankLines.push('WHERE  '+parsed.where.map(function(w,i){
        var noVal=['IS NULL','IS NOT NULL'].includes(w.op)||w.op==='';
        return (i>0?'  AND ':'')+w.col+(w.op?' '+w.op:'')+(noVal?'':' '+w.val);
      }).join('\n'));
    }
    rankLines.push(';');
    return rankLines.join('\n');
  }

  //  DELETE intent  early return 
  if (parsed.intents.includes('DELETE')) {
    var delLines = ['-- "'+parsed.rawText+'"', 'DELETE FROM '+mainTbl+' '+alias];
    var secondTbl = parsed.entities[1] ? parsed.entities[1].tables[0] : null;
    if (secondTbl) {
      var delAlias = 'T2';
      var delKey = mainEnt.joinKey || 'ID';
      delLines[1] += '\nINNER JOIN '+secondTbl+' '+delAlias+'\n    ON '+alias+'.'+delKey+' = '+delAlias+'.'+delKey;
    }
    var delWhere = parsed.updateWhere.length ? parsed.updateWhere : parsed.where;
    if (delWhere.length) {
      delLines.push('WHERE  '+delWhere.map(function(w,i){
        var noVal = ['IS NULL','IS NOT NULL'].includes(w.op)||w.op==='';
        return (i>0?'  AND ':'')+w.col+(w.op?' '+w.op:'')+(noVal?'':' '+w.val);
      }).join('\n'));
    } else if (secondTbl) {
      delLines.push('WHERE  T2.STATUS = \'INACTIVE\'');
    }
    delLines.push(';');
    return delLines.join('\n');
  }

  //  UNION / UNION ALL  early return 
  if (parsed.intents.includes('UNION') || parsed.intents.includes('UNION_ALL')) {
    var unionKw = parsed.intents.includes('UNION_ALL') ? 'UNION ALL' : 'UNION';
    var tbl2 = parsed.entities[1] ? parsed.entities[1].tables[0] : mainTbl;
    return '-- "'+parsed.rawText+'"\n'+
           'SELECT '+alias+'.*\n'+
           'FROM   '+mainTbl+' '+alias+'\n'+
           ((() => { if (parsed.where.length) { return 'WHERE  '+parsed.where.map(function(w){
             var noVal=['IS NULL','IS NOT NULL'].includes(w.op)||w.op==='';
             return w.col+(w.op?' '+w.op:'')+(noVal?'':' '+w.val);
           }).join('\n  AND  ')+'\n'; } return ''; })())+
           unionKw+'\n'+
           'SELECT T2.*\n'+
           'FROM   '+tbl2+' T2\n;';
  }

  //  CROSS JOIN  early return 
  if (parsed.intents.includes('CROSS_JOIN')) {
    var tbl2cx = parsed.entities[1] ? parsed.entities[1].tables[0] : '/* second_table */';
    var al2cx  = FUSION_ALIAS_MAP[tbl2cx] || 'T2';
    return '-- "'+parsed.rawText+'"\n'+
           '-- Intent: CROSS_JOIN\n'+
           'SELECT '+alias+'.*, '+al2cx+'.*\n'+
           'FROM   '+mainTbl+' '+alias+'\n'+
           'CROSS JOIN '+tbl2cx+' '+al2cx+'\n;';
  }

  //  RECONCILE (FULL OUTER JOIN + reconciliation status)  early return 
  if (parsed.intents.includes('RECONCILE')) {
    var rTbl2 = parsed.entities[1] ? parsed.entities[1].tables[0] : 'AP_INVOICE_LINES_ALL';
    var rKey  = mainEnt.joinKey || 'INVOICE_ID';
    var rAl1  = alias;
    var rAl2  = FUSION_ALIAS_MAP[rTbl2] || 'T2';
    // Determine descriptive columns based on known AP table pair
    var rHdrCols = (mainTbl==='AP_INVOICES_ALL')
      ? rAl1+'.INVOICE_NUM, '+rAl1+'.INVOICE_AMOUNT'
      : rAl1+'./* header_col */';
    var rDtlCols = (rTbl2==='AP_INVOICE_LINES_ALL')
      ? rAl2+'.LINE_NUMBER, '+rAl2+'.AMOUNT AS LINE_AMOUNT'
      : rAl2+'./* detail_col */';
    return [
      '-- "'+parsed.rawText+'"',
      '-- Intent: RECONCILE (FULL OUTER JOIN)',
      'SELECT COALESCE('+rAl1+'.'+rKey+', '+rAl2+'.'+rKey+') AS '+rKey+',',
      '       '+rHdrCols+',',
      '       '+rDtlCols+',',
      '       CASE',
      "           WHEN "+rAl1+"."+rKey+" IS NOT NULL AND "+rAl2+"."+rKey+" IS NOT NULL THEN 'MATCHED'",
      "           WHEN "+rAl1+"."+rKey+" IS NOT NULL AND "+rAl2+"."+rKey+" IS NULL     THEN 'HEADER ONLY - NO LINES'",
      "           WHEN "+rAl1+"."+rKey+" IS NULL     AND "+rAl2+"."+rKey+" IS NOT NULL THEN 'LINE ONLY - NO HEADER'",
      '       END AS RECONCILIATION_STATUS',
      'FROM   '+mainTbl+' '+rAl1,
      'FULL OUTER JOIN '+rTbl2+' '+rAl2,
      '    ON '+rAl1+'.'+rKey+' = '+rAl2+'.'+rKey+';',
    ].join('\n');
  }

  // Explicit joinPairs detected by "join X with Y using Z" pattern
  for (let jp of parsed.joinPairs){
    let tgtTbl = jp.tgt.tables[0];
    if (usedTables.includes(tgtTbl)) continue;
    usedTables.push(tgtTbl);
    let aliasN = FUSION_ALIAS_MAP[tgtTbl] || ('T'+(joins.length+2));
    let key = jp.key;
    // Use detected joinType for explicit pairs
    joins.push({ tbl:tgtTbl, alias:aliasN, lkey:key, rkey:key, type:parsed.joinType||'INNER JOIN' });
  }

  // Additional entities from text (not already covered by joinPairs)
  for (let ent of parsed.entities.slice(1)){
    let tgtTbl = ent.tables[0];
    if (usedTables.includes(tgtTbl)) continue;
    usedTables.push(tgtTbl);
    let aliasN = FUSION_ALIAS_MAP[tgtTbl] || ('T'+(joins.length+2));
    let suggestions = fusionJoinSuggest(mainTbl, tgtTbl);
    let lkey, rkey;
    if (suggestions.length) { lkey = suggestions[0].lc; rkey = suggestions[0].rc; }
    else if (mainEnt.joinKey) { lkey = mainEnt.joinKey; rkey = ent.joinKey || mainEnt.joinKey; }
    else { lkey = '/* join_key */'; rkey = '/* join_key */'; }
    joins.push({ tbl:tgtTbl, alias:aliasN, lkey:lkey, rkey:rkey, type:parsed.joinType||'LEFT OUTER JOIN' });
  }

  // wantDetail  auto join to detailJoin table
  nlBuildSQL_p2(FUSION_ALIAS_MAP, joins, mainEnt, mainTbl, parsed, usedTables);

  //  ANTI-JOIN: override joins to use LEFT JOIN + IS NULL 
  if (parsed.intents.includes('ANTI_JOIN')) {
    var antiTbl = (() => { if (parsed.entities[1]) { return parsed.entities[1].tables[0]; } if (joins.length) { return joins[0].tbl; } return 'ORDER_DETAILS'; })();
    var antiAlias = joins.length ? joins[0].alias : 'T2';
    var antiKey = mainEnt.joinKey || 'ID';
    joins = [{ tbl:antiTbl, alias:antiAlias, lkey:antiKey, rkey:antiKey, type:'LEFT OUTER JOIN' }];
    parsed.where.push({ col:antiAlias+'.'+antiKey, op:'IS NULL', val:'' });
  }

  //  SELF JOIN: add same-table join for manager/hierarchy pattern 
  nlBuildSQL_p3(joins, mainEnt, mainTbl, parsed);

  // Build FROM + JOIN clause
  var fromClause = mainTbl+' '+alias;
  for (let j of joins){
    let onStr = '\n'+j.type+' '+j.tbl+' '+j.alias+'\n    ON '+alias+'.'+j.lkey+' = '+j.alias+'.'+j.rkey;
    // ON-clause filters: for LEFT/RIGHT OUTER JOIN, right-side table filters go in ON, not WHERE
    // (WHERE would convert LEFT JOIN to INNER JOIN  Oracle Fusion AP training data pattern)
    if (parsed.onClauseFilters && parsed.onClauseFilters.length &&
        (j.type==='LEFT OUTER JOIN' || j.type==='RIGHT OUTER JOIN')) {
      for (let f of parsed.onClauseFilters){
        onStr += '\n    AND '+j.alias+'.'+f.col+' '+f.op+' '+f.val;
      }
    }
    fromClause += onStr;
  }

  //  CONDITIONALS (CASE WHEN) 
  function buildCaseWhen(cond, tableAlias) {
    var a = tableAlias || alias;
    return 'CASE WHEN '+a+'.'+cond.col+' IS NULL THEN \''+cond.thenVal+'\' ELSE '+a+'.'+cond.col+' END AS '+cond.col;
  }

  //  Aggregate expression helper 
  function aggExpr(col) {
    // For LEFT JOIN: if aggregate column belongs to the right-side table, use its alias (AIL, T2, etc.)
    // and wrap SUM/AVG in COALESCE to handle NULLs for rows with no matching detail rows
    var agAlias = alias;
    var agCol   = col;
    if (col !== '*' && joins.length && parsed.joinType === 'LEFT OUTER JOIN') {
      var rightTbl = joins[0].tbl;
      var rightAlias = joins[0].alias;
      // Check via FUSION_DB schema whether the column belongs to the right table
      var rightSchema = FUSION_DB.tables[rightTbl];
      var colBelongsToRight = rightSchema && rightSchema.cols.some(function(c){ return c.n === col; });
      // Also check NL_ENTITIES numCol
      var rightEnt = NL_ENTITIES.find(function(e){ return e.tables[0]===rightTbl; });
      if (colBelongsToRight || (rightEnt && rightEnt.numCol === col)) {
        agAlias = rightAlias;
      }
      // Normalise AP line amount alias  physical column name
      if (rightTbl === 'AP_INVOICE_LINES_ALL' && /^LINE_AMOUNT$/i.test(col)) {
        agAlias = rightAlias;
        agCol   = 'AMOUNT';
      }
    }
    var c  = agCol==='*' ? '*' : agAlias+'.'+agCol;
    var al = agCol==='*' ? parsed.agg.fn+'_TOTAL' : parsed.agg.fn+'_'+agCol.replaceAll(/[^A-Z0-9_]/g,'_');
    var fnStr;
    if (parsed.agg.fn === 'STDDEV') {
      fnStr = 'STDDEV('+c+')';
      al = 'STDDEV_'+( agCol==='*' ? 'VALUE' : agCol.replaceAll(/[^A-Z0-9_]/g,'_') );
    } else if (parsed.agg.fn === 'MEDIAN') {
      fnStr = 'MEDIAN('+c+')';
      al = 'MEDIAN_'+( agCol==='*' ? 'VALUE' : agCol.replaceAll(/[^A-Z0-9_]/g,'_') );
    } else if (parsed.agg.distinct && parsed.agg.fn === 'COUNT' && agCol !== '*') {
      fnStr = 'COUNT(DISTINCT '+c+')';
      al = 'DISTINCT_'+agCol.replaceAll(/[^A-Z0-9_]/g,'_')+'_COUNT';
    } else if (['SUM','AVG'].includes(parsed.agg.fn) && agAlias !== alias) {
      // LEFT JOIN: wrap aggregate on right-side column in COALESCE to handle no-line invoices
      fnStr = 'COALESCE('+parsed.agg.fn+'('+c+'), 0)';
      al = 'TOTAL_'+agCol.replaceAll(/[^A-Z0-9_]/g,'_');
    } else {
      fnStr = parsed.agg.fn+'('+c+')';
    }
    return fnStr+' AS '+al;
  }

  //  Window function intents  inject into selParts before main build 
  var windowSelParts = [];

  nlBuildSQL_p4(alias, mainEnt, parsed, windowSelParts);
  nlBuildSQL_p5(alias, mainEnt, parsed, windowSelParts);
  nlBuildSQL_p6(alias, mainEnt, parsed, windowSelParts);
  nlBuildSQL_p7(alias, mainEnt, parsed, windowSelParts);
  nlBuildSQL_p8(alias, mainEnt, parsed, windowSelParts);
  nlBuildSQL_p9(alias, mainEnt, parsed, windowSelParts);
  nlBuildSQL_p10(joins, parsed, windowSelParts);
  nlBuildSQL_p11(joins, parsed, windowSelParts);
  //  AP NULLIF division: line amount as % of invoice total 
  nlBuildSQL_p12(alias, joins, mainEnt, parsed, windowSelParts);

  //  SELECT columns 
  var selParts = [];
  if (parsed.agg) {
    if (parsed.selCols.length) {
      for (let col of parsed.selCols){ selParts.push(alias+'.'+col); }
      selParts.push(aggExpr(parsed.agg.col));
      for (let col of parsed.selCols){
        if (!parsed.groupByCols.some(function(g){ return g.col===col; }))
          parsed.groupByCols.push({ col:col, label:col, raw:false });
      }
    } else if (parsed.groupByCols.length) {
      for (let g of parsed.groupByCols){
        selParts.push((g.raw ? g.col : alias+'.'+g.col)+' AS '+g.label);
      }
      selParts.push(aggExpr(parsed.agg.col));
    } else if (parsed.wantDetail) {
      selParts.push(alias+'.*');
      var ac = parsed.agg.col==='*'?'*':alias+'.'+parsed.agg.col;
      selParts.push(parsed.agg.fn+'('+ac+') OVER () AS OVERALL_'+(parsed.agg.col==='*'?'COUNT':'VALUE'));
    } else {
      selParts.push(aggExpr(parsed.agg.col));
    }
  } else if (parsed.latestRecord) {
    selParts.push(alias+'.*');
    if (!parsed.onlyLeftCols && joins.length) { for (let j of joins){ selParts.push(j.alias+'.*'); } }
  } else if (parsed.dedupe) {
    selParts.push(alias+'.*');
  } else if (parsed.conditionals.length) {
    for (let cond of parsed.conditionals){ selParts.push(buildCaseWhen(cond, alias)); }
    selParts.push(alias+'.*');
  } else if (parsed.selCols.length) {
    for (let col of parsed.selCols){ selParts.push(alias+'.'+col); }
    if (!parsed.onlyLeftCols && joins.length) { for (let j of joins){ selParts.push(j.alias+'.*'); } }
  } else if (mainTbl==='AP_INVOICES_ALL' && joins.length && joins[0].tbl==='AP_INVOICE_LINES_ALL') {
    // AP Fusion: emit named columns for AP_INVOICES_ALL + AP_INVOICE_LINES_ALL join
    selParts.push('AI.INVOICE_ID', 'AI.INVOICE_NUM', 'AI.VENDOR_ID', 'AI.INVOICE_AMOUNT');
    if (!parsed.onlyLeftCols) {
      selParts.push('AIL.LINE_NUMBER', 'AIL.AMOUNT AS LINE_AMOUNT', 'AIL.LINE_TYPE_LOOKUP_CODE');
    }
  } else {
    selParts.push(alias+'.*');
    if (!parsed.onlyLeftCols && joins.length) { for (let j of joins){ selParts.push(j.alias+'.*'); } }
  }

  //  WHERE clause 
  var whereParts = [];
  for (let [i, w] of parsed.where.entries()){
    let noVal = ['IS NULL','IS NOT NULL'].includes(w.op) || w.op==='';
    let expr = (() => { if (noVal) { return w.col+(w.op?' '+w.op:''); } return w.col+' '+w.op+' '+w.val; })();
    // Replace hardcoded T1. with actual main table alias (e.g. AI for AP_INVOICES_ALL)
    expr = expr.replaceAll(/\bT1\./g, alias+'.');
    whereParts.push((i===0?'':'AND    ')+expr);
  }

  // EXISTS / NOT EXISTS correlated subquery
  nlBuildSQL_p13(alias, mainEnt, parsed, whereParts);
  nlBuildSQL_p14(alias, mainEnt, parsed, whereParts);

  // SUBQUERY: inject subquery into WHERE
  nlBuildSQL_p15(alias, mainEnt, mainTbl, parsed, whereParts);

  //  HAVING clause 
  var havingClause = '';
  if (parsed.having) {
    // Replace __AGG__ placeholder with real aggregate expression
    if (parsed.agg) {
      var aggStr = parsed.agg.fn+'('+( parsed.agg.col==='*' ? '*' : alias+'.'+parsed.agg.col )+')';
      havingClause = 'HAVING '+parsed.having.replace('__AGG__', aggStr);
    } else {
      havingClause = 'HAVING '+parsed.having;
    }
  }
  //  AP DISCREPANCY HAVING: invoice amount  sum of lines 
  if (parsed.intents.includes('DISCREPANCY') && !havingClause) {
    var discJoinAlias = (joins.length ? joins[0].alias : 'AIL');
    havingClause = 'HAVING '+alias+'.INVOICE_AMOUNT <> COALESCE(SUM('+discJoinAlias+'.AMOUNT), 0)';
  }

  //  ASSEMBLE SQL 
  var lines = [];
  lines.push('-- "'+parsed.rawText.replaceAll('--','-')+'"');
  if (parsed.intents.length) lines.push('-- Intent: '+parsed.intents.join(', '));

  //  CTE wrapper helper 
  function wrapCTE(innerLines) {
    var lbl = parsed.cteLabel || 'CTE_RESULTS';
    // Pull SELECT from innerLines, indent it as CTE body
    var inner = innerLines.slice(2).join('\n'); // skip the 2 comment lines
    var cteLines = [];
    cteLines.push('WITH '+lbl+' AS (');
    for (let l of inner.split('\n')){ cteLines.push('  '+l); }
    cteLines.push(')',
                  'SELECT *',
                  'FROM   '+lbl+';');
    return cteLines;
  }

  if (parsed.latestRecord) {
    var partKey = mainEnt.joinKey || 'PERSON_ID';
    var sortCol = mainEnt.dateCol || 'CREATION_DATE';
    lines.push('SELECT *',
               'FROM (',
               '  SELECT '+alias+'.*,',
               '         ROW_NUMBER() OVER (PARTITION BY '+alias+'.'+partKey,
               '                           ORDER BY '+alias+'.'+sortCol+' DESC) AS RN',
               '  FROM   '+fromClause);
    if (whereParts.length) lines.push('  WHERE  '+whereParts.join('\n  '));
    lines.push(') WHERE RN = 1');
  } else if (parsed.dedupe) {
    var dedupeKey = mainEnt.joinKey || 'PERSON_ID';
    lines.push('SELECT *',
               'FROM (',
               '  SELECT '+alias+'.*,',
               '         ROW_NUMBER() OVER (PARTITION BY '+alias+'.'+dedupeKey,
               '                           ORDER BY '+alias+'.CREATION_DATE DESC) AS RN',
               '  FROM   '+fromClause);
    if (whereParts.length) lines.push('  WHERE  '+whereParts.join('\n  '));
    lines.push(') WHERE RN = 1');
  } else {
    // Merge window/special cols into selParts
    if (windowSelParts.length) {
      // Append window cols after the selected cols (works for bare alias.* too)
      selParts = selParts.concat(windowSelParts);
    }
    lines.push('SELECT '+selParts.join(',\n       '),
               'FROM   '+fromClause);
    if (whereParts.length) lines.push('WHERE  '+whereParts.join('\n       '));
    if (parsed.groupByCols.length && parsed.agg) {
      lines.push('GROUP BY '+parsed.groupByCols.map(function(g){
        return g.raw ? g.col : alias+'.'+g.col;
      }).join(',\n         '));
    }
    if (havingClause) lines.push(havingClause);
    if (parsed.orderBy.length) {
      lines.push('ORDER BY '+parsed.orderBy.map(function(o){
        return o.col.replaceAll(/\bT1\./g, alias+'.') + ' ' + o.dir;
      }).join(', '));
    }
    if (parsed.limit) lines.push('FETCH FIRST '+parsed.limit+' ROWS ONLY');
  }

  lines.push(';');

  // Wrap in CTE if requested
  if (parsed.cte) lines = lines.slice(0,2).concat(wrapCTE(lines));

  return lines.join('\n');
}

// --- helpers extracted from nlDescribeParsed (behavior-identical) ---
function nlDescribeParsed_p1(parsed, parts){
if (parsed.entities.length)      parts.push(' Tables: <b>'+parsed.entities.map(function(e){return e.tables[0];}).join('  ')+'</b>');
}
function nlDescribeParsed_p2(parsed, parts){
if (parsed.joinPairs.length)     parts.push(' Join key: <b>'+parsed.joinPairs.map(function(j){return j.key;}).join(', ')+'</b>');
}
function nlDescribeParsed_p3(parsed, parts){
if (parsed.groupByCols.length)   parts.push(' Group By: <b>'+parsed.groupByCols.map(function(g){return g.label;}).join(', ')+'</b>');
}
function nlDescribeParsed_p4(parsed, parts){
if (parsed.orderBy.length)       parts.push(' Order: <b>'+parsed.orderBy.map(function(o){return o.col+' '+o.dir;}).join(', ')+'</b>');
}

function nlDescribeParsed(parsed) {
  var parts = [];
  if (parsed.intents.length)       parts.push(' Intent: <b>'+parsed.intents.join(' + ')+'</b>');
  nlDescribeParsed_p1(parsed, parts);
  nlDescribeParsed_p2(parsed, parts);
  if (parsed.joinType && parsed.joinType !== 'LEFT OUTER JOIN') parts.push(' Join type: <b>'+parsed.joinType+'</b>');
  if (parsed.agg)                   parts.push(' Aggregate: <b>'+parsed.agg.fn+'('+(parsed.agg.col||'*')+')</b>');
  nlDescribeParsed_p3(parsed, parts);
  if (parsed.having)               parts.push(' Having: <b>'+parsed.having+'</b>');
  if (parsed.selCols.length)       parts.push(' Columns: <b>'+parsed.selCols.join(', ')+'</b>');
  if (parsed.where.length)         parts.push(' Filters: <b>'+parsed.where.length+'</b>');
  if (parsed.subquery)             parts.push(' Subquery: <b>'+parsed.subquery.type+'</b>');
  if (parsed.cte)                  parts.push(' CTE: <b>'+parsed.cteLabel+'</b>');
  if (parsed.latestRecord)         parts.push(' <b>Latest record (ROW_NUMBER)</b>');
  if (parsed.dedupe)               parts.push(' <b>Deduplicate</b>');
  if (parsed.conditionals.length)  parts.push(' <b>CASE WHEN null handling</b>');
  nlDescribeParsed_p4(parsed, parts);
  if (parsed.limit)                parts.push(' Limit: <b>'+parsed.limit+' rows</b>');
  return parts.join('&nbsp;&nbsp;|&nbsp;&nbsp;');
}

//  NL Inline Assist (context-aware, injected into each card) 

// Voice input using Web Speech API
function startVoiceInput(inputId, statusId, onDone) {
  var SR = globalThis.SpeechRecognition || globalThis.webkitSpeechRecognition;
  if (!SR) {
    alert('Voice input is not supported in this browser. Please use Chrome or Edge.');
    return;
  }
  var inp    = document.getElementById(inputId);
  var status = statusId ? document.getElementById(statusId) : null;
  var micBtn = document.getElementById(inputId + '_mic');

  var rec = new SR();
  rec.lang = 'en-US';
  rec.interimResults = true;
  rec.maxAlternatives = 1;

  if (micBtn) micBtn.classList.add('listening');
  if (status) status.textContent = 'Listening speak now';

  rec.onresult = function(e) {
    var transcript = '';
    for (var i = e.resultIndex; i < e.results.length; i++) {
      transcript += e.results[i][0].transcript;
    }
    if (inp) inp.value = transcript;
    if (status) { var lastIx = e.results.length-1; status.textContent = e.results[lastIx].isFinal ? 'Got it!' : 'Listening'; }
  };

  rec.onerror = function(e) {
    if (micBtn) micBtn.classList.remove('listening');
    if (status) status.textContent = 'Error: ' + (e.error || 'unknown');
  };

  rec.onend = function() {
    if (micBtn) micBtn.classList.remove('listening');
    if (status) { status.textContent = inp && inp.value ? ' Ready  click Apply' : ''; }
    if (onDone && inp && inp.value) onDone(inp.value);
  };

  rec.start();
}

// Connection helpers. "connected" = a real key OR demo mode; demo = flag set with no real key.
function aiConnected(){ return !!((S.apiKey && S.apiKey.trim()) || S.demoMode); }
function aiIsDemo(){ return !!S.demoMode && !(S.apiKey && S.apiKey.trim()); }

// Session-scoped API key setter shared by the inline NL connect controls.
function nlSetApiKey(key){
  S.apiKey = (key||'').trim();
  if (S.apiKey) { sessionStorage.setItem('sqg_key', S.apiKey); S.demoMode=false; sessionStorage.removeItem('sqg_demo'); }
  else sessionStorage.removeItem('sqg_key');
  for (let k of ['joins','filter','groupby']){ try{ refreshCard(k); }catch(e){ console.debug('sqg: card not rendered yet', e); } }
  refreshSQL();
  notify(S.apiKey ? 'API connected for this session  natural language now uses Claude' : 'API disconnected  natural language uses the offline engine','ok');
}

// Real validation against Anthropic before ever showing "API connected" - any non-empty
// string used to be accepted at face value, which meant a GitHub token or plain garbage
// text would silently claim to be connected. This makes one minimal-cost live request
// (max_tokens:1) so only a genuinely working Anthropic key is ever marked connected.
async function nlValidateApiKey(key){
  if (!/^sk-ant-/.test(key)) {
    notify('That doesn\'t look like an Anthropic API key (should start with "sk-ant-"). A GitHub, OpenAI, or other provider key will not work here.','err');
    return false;
  }
  try {
    var r = await fetchT('https://api.anthropic.com/v1/messages', {method:'POST',headers:{'x-api-key':key,'anthropic-version':'2023-06-01','content-type':'application/json','anthropic-dangerous-direct-browser-access':'true'},body:JSON.stringify({model:S.model||'claude-opus-4-8',max_tokens:1,messages:[{role:'user',content:'hi'}]})}, 15000);
    var d = await r.json();
    if (d && d.error) {
      notify('Invalid Anthropic API key: '+(d.error.message||'authentication failed')+(r.status===401?'  check your key':''),'err');
      return false;
    }
    return true;
  } catch(e) {
    notify(isTimeout(e) ? 'Timed out reaching Anthropic to validate the key.' : 'Could not reach Anthropic to validate the key: '+e.message,'err');
    return false;
  }
}

// Demo mode: simulate the connected experience with the offline engine (no real Claude call).
function nlSetDemoMode(on){
  S.demoMode = !!on;
  if (on){ S.apiKey=''; sessionStorage.removeItem('sqg_key'); sessionStorage.setItem('sqg_demo','1'); }
  else sessionStorage.removeItem('sqg_demo');
  for (let k of ['joins','filter','groupby']){ try{ refreshCard(k); }catch(e){ console.debug('sqg: card not rendered yet', e); } }
  refreshSQL();
  notify(on ? 'Demo mode ON  AI buttons simulate results with the offline engine (not real Claude)' : 'Demo mode OFF','ok');
}

// Build a reusable inline NL section DOM element.
// kind: 'filter' | 'groupby' | 'join'  when the API is connected, 'filter'/'groupby' route
// the Apply through Claude (nlAIApply); everything else uses the offline onApply engine.
function buildNLInlineSection(inputId, placeholder, tip, onApply, kind) {
  var wrap = document.createElement('div');
  wrap.style.cssText = 'border:1px dashed rgba(139,92,246,.35);border-radius:6px;padding:10px 12px;margin-top:10px;background:rgba(139,92,246,.04)';

  var real = !!(S.apiKey && S.apiKey.trim());
  var demo = aiIsDemo();
  var connected = real || demo;
  var aiKinds = (kind==='filter' || kind==='groupby');

  function runApply(){
    // Real key + an AI-capable section  Claude. Demo or offline  the offline engine.
    if (real && aiKinds) nlAIApply(kind, inputId, inputId+'_apply', onApply);
    else onApply();
  }

  var hdr = document.createElement('div');
  hdr.style.cssText = 'font-size:11px;font-weight:700;color:var(--purple);margin-bottom:7px;display:flex;align-items:center;gap:6px';
  hdr.innerHTML = ' Describe in plain English <span style="font-weight:400;color:var(--text3)"> the engine reads your sources &amp; columns</span>';
  // Right-aligned API connect control (the boxed area in the panel header)
  var spacer = document.createElement('span'); spacer.style.flex = '1'; hdr.appendChild(spacer);
  var ctrl = document.createElement('span'); ctrl.style.cssText = 'display:flex;align-items:center;gap:5px;font-weight:400';
  if (real) {
    ctrl.innerHTML = '<span style="color:#22c55e;font-weight:700;font-size:10px" title="Natural language uses Claude this session"> AI on</span>'+
      '<button class="btn btn-xs btn-danger" title="Disconnect API for this session" style="padding:0 6px">&#x2715;</button>';
    ctrl.querySelector('button').onclick = function(){ nlSetApiKey(''); };
  } else if (demo) {
    ctrl.innerHTML = '<span style="color:var(--amber,#f59e0b);font-weight:700;font-size:10px" title="Simulated  offline engine, not real Claude"> Demo mode</span>'+
      '<button class="btn btn-xs btn-danger" title="Exit demo mode" style="padding:0 6px">&#x2715;</button>';
    ctrl.querySelector('button').onclick = function(){ nlSetDemoMode(false); };
  } else {
    ctrl.innerHTML = '<button class="btn btn-xs" style="background:rgba(6,182,212,.12);color:#06b6d4;border-color:rgba(6,182,212,.35);padding:1px 8px;font-size:10px">&#128268; Connect API</button>';
    ctrl.querySelector('button').onclick = function(){ connRow.style.display = connRow.style.display==='none'?'flex':'none'; if(connRow.style.display!=='none'){ var k=connRow.querySelector('input'); if(k) k.focus(); } };
  }
  hdr.appendChild(ctrl);
  wrap.appendChild(hdr);

  // Inline connect row (hidden until "Connect API" is clicked)
  var connRow = document.createElement('div');
  connRow.style.cssText = 'display:none;gap:6px;align-items:center;margin-bottom:7px';
  if (!connected) {
    var keyInp = document.createElement('input');
    keyInp.type = 'password'; keyInp.placeholder = 'Paste Anthropic API key (sk-ant-)  session only';
    keyInp.className = 'cell-inp'; keyInp.style.cssText = 'flex:1;font-size:11px'; keyInp.autocomplete = 'off';
    var connBtn = document.createElement('button');
    connBtn.className = 'btn btn-xs'; connBtn.style.cssText = 'background:rgba(34,197,94,.15);color:#22c55e;border-color:rgba(34,197,94,.4);white-space:nowrap';
    connBtn.textContent = 'Connect';
    connBtn.onclick = function(){ var v=keyInp.value.trim(); if(!v){ keyInp.focus(); return; } nlSetApiKey(v); };
    keyInp.addEventListener('keydown', function(e){ if(e.key==='Enter') connBtn.onclick(); });
    var demoBtn = document.createElement('button');
    demoBtn.className = 'btn btn-xs'; demoBtn.style.cssText = 'background:rgba(245,158,11,.15);color:var(--amber,#f59e0b);border-color:rgba(245,158,11,.4);white-space:nowrap';
    demoBtn.innerHTML = ' Try demo';
    demoBtn.title = 'Simulate the AI flow with the offline engine (no key, not real Claude)';
    demoBtn.onclick = function(){ nlSetDemoMode(true); };
    connRow.appendChild(keyInp); connRow.appendChild(connBtn); connRow.appendChild(demoBtn);
    wrap.appendChild(connRow);
  }

  var row = document.createElement('div');
  row.style.cssText = 'display:flex;gap:6px';

  var inp = document.createElement('input');
  inp.type = 'text';
  inp.id   = inputId;
  inp.className = 'cell-inp';
  inp.placeholder = placeholder;
  inp.style.cssText = 'flex:1;font-size:12px';
  inp.addEventListener('keydown', function(e){ if(e.key==='Enter') runApply(); });

  var micBtn = document.createElement('button');
  micBtn.className = 'btn btn-sm btn-mic';
  micBtn.id = inputId + '_mic';
  micBtn.title = 'Speak your query (voice input)';
  micBtn.innerHTML = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0"><path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"></path><path d="M19 10v2a7 7 0 0 1-14 0v-2"></path><line x1="12" y1="19" x2="12" y2="23"></line><line x1="8" y1="23" x2="16" y2="23"></line></svg><span style="font-size:11px">Speak</span>';
  micBtn.onclick = function(){ startVoiceInput(inputId, inputId+'_vstatus', null); };

  var applyBtn = document.createElement('button');
  applyBtn.className = 'btn btn-sm';
  applyBtn.id = inputId + '_apply';
  applyBtn.style.cssText = 'background:var(--purple-bg);color:var(--purple);border-color:rgba(139,92,246,.3);white-space:nowrap;flex-shrink:0';
  applyBtn.innerHTML = (() => { if (real && aiKinds) { return ' Apply (AI)'; } if (demo && aiKinds) { return ' Apply (demo)'; } return ' Apply'; })();
  applyBtn.onclick = runApply;

  row.appendChild(inp);
  row.appendChild(micBtn);
  row.appendChild(applyBtn);
  wrap.appendChild(row);

  // Voice status line
  var vstatus = document.createElement('div');
  vstatus.id = inputId + '_vstatus';
  vstatus.className = 'voice-status';
  wrap.appendChild(vstatus);

  if (tip) {
    var tipEl = document.createElement('div');
    tipEl.style.cssText = 'font-size:10px;color:var(--text3);margin-top:5px;line-height:1.6';
    tipEl.innerHTML = tip;
    wrap.appendChild(tipEl);
  }
  return wrap;
}

// Extract the first JSON object from a model response (tolerates ```json fences / prose).
function nlParseJSON(s){
  if(!s) return null;
  var txt = String(s).replaceAll(/```json/gi,'').replaceAll('```','').trim();
  var i = txt.indexOf('{'), j = txt.lastIndexOf('}');
  if(i<0 || j<i) return null;
  try { return JSON.parse(txt.slice(i, j+1)); } catch(e){ console.debug('sqg: model JSON unparsable', e); return null; }
}

// AI-powered apply for the inline NL sections (used when an API key is connected).
// Falls back to the offline engine if the model call fails or returns nothing usable.
async function nlAIApply(kind, inputId, applyBtnId, fallback){
  var inp = document.getElementById(inputId);
  var text = (inp && inp.value || '').trim();
  if(!text) return;
  // Build column context from loaded sources so the model uses real qualified names.
  var cols = [];
  for (let s of S.sources||[]){
    let ref = s.alias || s.table || 'T';
    for (let c of (s.columns||[])){ cols.push(ref+'.'+c.name+(c.dataType?' ('+c.dataType+')':'')); }
  }
  var ctx = cols.length ? cols.join(', ') : '(no columns loaded  infer reasonable column names)';
  var prompt;
  if(kind==='filter'){
    prompt = 'You convert a plain-English filter into Oracle SQL WHERE conditions.\n'+
      'Available columns (prefer these exact qualified names): '+ctx+'\n'+
      'Request: "'+text+'"\n'+
      'Return ONLY JSON, no prose or markdown: '+
      '{"conditions":[{"expr":"<one SQL boolean condition, e.g. S2.STATUS = \'ACTIVE\'>","logic":"AND"}]}';
  } else {
    prompt = 'You convert a plain-English grouping/aggregation request into Oracle SQL parts.\n'+
      'Available columns (prefer these exact qualified names): '+ctx+'\n'+
      'Request: "'+text+'"\n'+
      'Return ONLY JSON, no prose or markdown: '+
      '{"dims":[{"col":"<qualified column>","alias":"<short alias>"}],'+
      '"aggs":[{"fn":"SUM|COUNT|AVG|MIN|MAX|COUNT DISTINCT","col":"<qualified column or * for count>","alias":"<alias>"}]}';
  }
  var btn = document.getElementById(applyBtnId);
  var prevTxt = btn ? btn.innerHTML : '';
  if(btn){ btn.disabled = true; btn.innerHTML = ' AI'; }
  var res = await callAI(prompt, 1500);
  if(btn){ btn.disabled = false; btn.innerHTML = prevTxt; }
  if(!res){ return; }  // callAI already surfaced the error
  var data = nlParseJSON(res);
  if(!data){ notify('Could not read AI response  using offline engine','err'); if(fallback){ fallback(); } return; }

  var added = 0;
  if(kind==='filter'){
    for (let c of (data.conditions||[])){
      if(!c || !c.expr) continue;
      S.filters.push({ id:uid(), logic:(String(c.logic).toUpperCase()==='OR'?'OR':'AND'), clause:'WHERE', srcId:'', col:c.expr, op:'', val:'' });
      added++;
    }
    if(added){ inp.value=''; refreshCard('filter'); refreshSQL(); notify(added+' condition'+(added>1?'s':'')+' added by AI','ok'); }
    else { notify('AI found no filter  using offline engine','err'); if(fallback) fallback(); }
  } else {
    var gb = S.groupBy || { dims:[], aggs:[], having:[] };
    for (let d of (data.dims||[])){
      if(!d || !d.col) continue;
      gb.dims.push({ id:uid(), col:d.col, alias:d.alias || d.col.split('.').pop() });
      added++;
    }
    for (let a of (data.aggs||[])){
      if(!a || !a.fn) continue;
      gb.aggs.push({ id:uid(), fn:a.fn, col:a.col||'', val:'', alias:a.alias || (a.fn.replaceAll(/\s+/g,'_')+'_'+String(a.col||'VAL').split('.').pop()) });
      added++;
    }
    if(added){ S.groupBy=gb; inp.value=''; refreshCard('groupby'); refreshSQL(); notify(added+' expression'+(added>1?'s':'')+' added by AI','ok'); }
    else { notify('AI found no grouping  using offline engine','err'); if(fallback) fallback(); }
  }
}

// Resolve a column name against loaded sources  returns "ALIAS.COL" if found, else just COL
function nlResolveColInSources(colName) {
  if (!colName) return colName;
  var found = null;
  for (let src of S.sources){
    if (!found) {
      let c = src.columns.find(function(c){ return c.name.toUpperCase() === colName.toUpperCase(); });
      if (c) found = (src.alias||src.table)+'.'+c.name;
    }
  }
  return found || colName;
}

// Detect column name from free text against explicit cols + source columns
function nlColFromText(text) {
  var textL = text.toLowerCase(), textLU = textL.replaceAll('_',' ');
  var col = null;
  for (let ec of NL_EXPLICIT_COLS){
    if (!col && ec.words.some(function(w){ return textL.includes(w) || textLU.includes(w.replaceAll('_',' ')); })) col = ec.col;
    if (!col && textL.includes(ec.col.toLowerCase())) col = ec.col;
  }
  if (!col) for (let h of NL_COL_HINTS){
    if (!col && h.words.some(function(w){ return textL.includes(w); })) col = h.col;
  }
  return col ? nlResolveColInSources(col) : null;
}

//  NL Date Parser: "1st jan 2020" / "01/01/2020" / "2020-01-01"  Oracle TO_DATE 
var NL_MONTH_MAP = {
  jan:'JAN',january:'JAN',feb:'FEB',february:'FEB',mar:'MAR',march:'MAR',
  apr:'APR',april:'APR',may:'MAY',jun:'JUN',june:'JUN',jul:'JUL',july:'JUL',
  aug:'AUG',august:'AUG',sep:'SEP',sept:'SEP',september:'SEP',
  oct:'OCT',october:'OCT',nov:'NOV',november:'NOV',dec:'DEC',december:'DEC'
};
function nlParseDate(raw) {
  var s = (raw||'').trim().replaceAll(rx([String.raw`(\d+)(st|nd|rd|th)\b`], 'gi'),'$1'); // strip ordinals
  var m;
  // "1 jan 2020" / "1 january 2020"
  m = s.match(/^(\d{1,2})\s+([a-z]+)\s+(\d{4})$/i);
  if (m) {
    var mon = NL_MONTH_MAP[m[2].toLowerCase()];
    if (mon) return "TO_DATE('"+m[1].padStart(2,'0')+'-'+mon+'-'+m[3]+"','DD-MON-YYYY')";
  }
  // "jan 1 2020" / "january 1, 2020"
  m = s.match(/^([a-z]+)\s+(\d{1,2})[,\s]+(\d{4})$/i);
  if (m) {
    var mon2 = NL_MONTH_MAP[m[1].toLowerCase()];
    if (mon2) return "TO_DATE('"+m[2].padStart(2,'0')+'-'+mon2+'-'+m[3]+"','DD-MON-YYYY')";
  }
  // "2020-01-01"
  m = s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/);
  if (m) return "TO_DATE('"+m[3].padStart(2,'0')+'/'+m[2].padStart(2,'0')+'/'+m[1]+"','DD/MM/YYYY')";
  // "01/01/2020" or "01-01-2020"
  m = s.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/);
  if (m) return "TO_DATE('"+m[1].padStart(2,'0')+'/'+m[2].padStart(2,'0')+'/'+m[3]+"','DD/MM/YYYY')";
  // Already looks like a quoted/bare Oracle date  return as-is
  return s;
}

// Broad date string pattern (captures "1st jan 2020", "1 january 2020", "01/01/2020", "2020-01-01")
var NL_DATE_STR_RE = rx([String.raw`\d{1,2}(?:st|nd|rd|th)?\s+[a-z]+\s+\d{4}|\d{4}[-/]\d{1,2}[-/]\d{1,2}|\d{1,2}[-/]\d{1,2}[-/]\d{4}|[a-z]+\s+\d{1,2}[,\s]+\d{4}`], 'gi');

//  NL  JOIN 
// --- helpers extracted from nlApplyToJoinInput (behavior-identical) ---
function nlApplyToJoinInput_p1(mentioned, t, tU){
for (let src of S.sources){
    let tblL  = src.table.toLowerCase();
    let tblU2 = tblL.replaceAll('_',' ');
    let aliL  = (src.alias||'').toLowerCase();
    let found = t.includes(' '+tblL+' ') || tU.includes(' '+tblU2+' ')
             || (aliL && (t.includes(' '+aliL+' ') || t.includes(' '+aliL+',')));
    if (!found) {
      for (let e of NL_ENTITIES){
        if (!found && e.tables[0]===src.table && nlHasPhrase(t, tU, e.words)) found = true;
      }
    }
    if (found && !mentioned.some(function(m){ return m.id===src.id; })) mentioned.push(src);
  }
}

function nlApplyToJoinInput(inputId) {
  var text = (document.getElementById(inputId)||{}).value;
  if (!text || !text.trim()) return;
  text = text.trim();
  var t  = ' ' + text.toLowerCase().replaceAll(/[^\w\s.]/g,' ') + ' ';
  var tU = t.replaceAll('_',' ');

  // Find which existing sources are mentioned (by table name, alias, or entity words)
  var mentioned = [];
  nlApplyToJoinInput_p1(mentioned, t, tU);

  // Detect join key
  var usingM = text.match(rx([String.raw`\b(?:using|on|by|via|with key|based on)\s+([\w\s]+?)(?:\s*$|,|\.|\band\b|\bwhere\b)`], 'i'));
  var keyPhrase = usingM ? usingM[1].trim() : null;
  var resolvedKey = keyPhrase ? nlResolveJoinKey(keyPhrase, null, null) : null;

  //  JOIN TYPE DETECTION (trained on 188 AP join examples) 
  // Priority: explicit keyword  FULL OUTER semantic  RIGHT semantic  INNER semantic  LEFT semantic  Fusion default
  var joinType = null;

  //  1. Explicit join-type keywords (user typed it directly) 
  if      (/\bleft\s+outer\s+join\b|\bleft\s+join\b/.test(t))  { joinType = 'LEFT OUTER JOIN';  }
  else if (/\bright\s+outer\s+join\b|\bright\s+join\b/.test(t)) { joinType = 'RIGHT OUTER JOIN'; }
  else if (/\bfull\s+outer\s+join\b|\bfull\s+join\b/.test(t))  { joinType = 'FULL OUTER JOIN';  }
  else if (/\bcross\s+join\b/.test(t))                           { joinType = 'CROSS JOIN';       }
  else if (/\binner\s+join(?:ed)?\b/.test(t))                    { joinType = 'INNER JOIN';       }

  //  1b. CROSS JOIN semantic cues  Cartesian product / all combinations / every row  every row 
  if (!joinType) {
    var CROSS_PATTERNS = [
      /\bcartesian\s+product\b/,
      /\ball\s+(?:possible\s+)?combinations?\s+of\b/,
      /\bevery\s+(?:possible\s+)?combination\b/,
      /\ball\s+(?:possible\s+)?pairings?\b/,
      /\ball\s+pairings?\s+between\b/,
      /\ball\s+(?:header[\s-]?line|header\s+and\s+line)\s+combinations?\b/,
      /\bcombine\s+every\s+(?:row|record)\s+from\b/,
      /\bevery\s+(?:row|record)\s+from\b.*\bwith\s+every\s+(?:row|record)\s+from\b/,
      /\bgenerate\s+all\s+(?:possible\s+)?(?:combinations?|pairings?)\b/,
    ];
    if (CROSS_PATTERNS.some(function(rx){ return rx.test(t); })) joinType = 'CROSS JOIN';
  }

  //  2. FULL OUTER JOIN semantic cues 
  // "regardless of whether they match", "all from both tables", "reconcile/reconciliation"
  // "unmatched rows from either side", "complete view of both tables"
  // "MATCHED/HEADER ONLY/LINE ONLY classification", "data quality report"
  if (!joinType) {
    var FULL_PATTERNS = [
      /\bregardless\s+of\s+whether\s+they\s+match\b/,
      /\beven\s+where\s+there\s+is\s+no\s+relationship\b/,
      /\bunmatched\s+(?:rows?|records?)\s+from\s+either\s+side\b/,
      /\bkeep\s+everything\s+from\s+both\s+sides\b/,
      /\bcomplete\s+view\s+of\s+both\s+tables?\b/,
      /\ball\s+(?:rows?|records?)\s+from\s+both\s+tables?\b/,
      /\breconcili(?:e|ation|se)\b/,
      /\bheader[\s-]only\b|\bline[\s-]only\b/,
      /\bmatched\s+vs\s+unmatched\b/,
      /\bdata\s+quality\s+report\b/,
      /\ball\s+(?:invoice\s+)?headers?\s+and\s+all\s+(?:invoice\s+)?lines?\b/,
      /\beverything\s+from\s+both\s+(?:sides?|tables?)\b/,
      /\borphan\s+invoices?\s+and\s+(?:all\s+)?orphan\s+lines?\b/,
      /\bfull\s+outer\b/,
      // "all unmatched records from both [tables] combined"  symmetric unmatched query
      /\ball\s+unmatched\s+(?:records?|rows?)\b/,
      /\bunmatched\s+(?:records?|rows?)\s+from\s+both\b/,
      /\bfrom\s+both\s+(?:ap_invoices_all\s+and\s+ap_invoice_lines_all|tables?)\s+combined\b/,
      /\bcombined?\s+from\s+both\b|\bmerged?\s+from\s+both\b/,
      /\ball\s+(?:records?|rows?)\s+from\s+(?:ap_invoices_all\s+and\s+ap_invoice_lines_all)\b/,
      // "even if they don't match"  symmetric, both tables preserved (row 2)
      /\beven\s+if\s+they\s+don.t\s+match\b/,
      // "all invoices and all lines"  without "headers" keyword (row 8)
      /\ball\s+invoices?\s+and\s+all\s+(?:invoice\s+)?lines?\b/,
      // "join both tables fully" / "nulls from both sides" (row 11)
      /\bjoin\s+both\s+tables?\s+fully\b|\bnulls?\s+from\s+both\s+sides\b/,
      // "exist only in X or only in Y but not in both"  symmetric difference (row 13)
      /\bbut\s+not\s+in\s+both\b/,
      rx([String.raw`\bonly\s+in\s+ap_invoices_all\b.*\bor\s+only\s+in\b|\bonly\s+in\s+ap_invoice_lines_all\b.*\bor\s+only\s+in\b`], ''),
      // "unmatched records from either table"  "table" variant of "either side" (row 14)
      /\bunmatched\s+(?:records?|rows?)\s+from\s+either\s+(?:side|table)\b/,
      // "invoices without lines and lines without headers"  both-side orphans (row 14)
      /\binvoices?\s+without\s+(?:any\s+)?lines?\s+and\s+lines?\s+without\s+headers?\b/,
      // "matching ... in the other table" / "missing from one of the two tables" (rows 15, 18)
      /\bmatching\b.*\bin\s+the\s+other\s+table\b/,
      /\bmissing\s+from\s+one\s+of\s+the\s+two\s+tables?\b/,
    ];
    if (FULL_PATTERNS.some(function(rx){ return rx.test(t); })) joinType = 'FULL OUTER JOIN';
  }

  //  3. RIGHT OUTER JOIN semantic cues 
  // Signals: subject/focus is on LINES table (right side), user wants ALL lines preserved
  // "all lines even if no parent/header", "every line from AP_INVOICE_LINES_ALL"
  // "orphan lines", "lines without a parent invoice", "right join"
  if (!joinType) {
    var RIGHT_PATTERNS = [
      // All lines regardless of header
      /\ball\s+(?:invoice\s+)?lines?\s+(?:even\s+if|whether\s+or\s+not|regardless)\b/,
      /\ball\s+(?:records?\s+from\s+)?ap_invoice_lines_all\b/,
      /\bevery\s+(?:invoice\s+)?line\s+from\s+ap_invoice_lines_all\b/,
      /\ball\s+ap_invoice_lines_all\s+records?\b/,
      // Whether or not / regardless of header
      /\bwhether\s+or\s+not\s+they\s+have\s+a\s+(?:parent|header|matching)\b/,
      /\bregardless\s+of\s+whether\s+they\s+have\s+a\s+(?:parent|header)\b/,
      /\beven\s+if\s+(?:the\s+)?(?:header|parent\s+invoice?)\s+is\s+missing\b/,
      /\beven\s+if\s+(?:no|they\s+don.t\s+have\s+a)\s+(?:matching\s+)?(?:parent|header)\b/,
      // Lines without headers (orphan lines)
      /\blines?\s+(?:that\s+)?(?:have\s+)?no\s+(?:matching\s+)?(?:parent\s+)?(?:invoice|header)\b/,
      /\blines?\s+(?:that\s+are\s+)?missing\s+(?:their\s+)?(?:parent\s+)?(?:invoice\s+)?header\b/,
      /\blines?\s+(?:from\s+ap_invoice_lines_all\s+)?where\s+no\s+matching\s+record\s+exists\b/,
      /\blines?\s+(?:in\s+ap_invoice_lines_all\s+)?(?:that\s+)?don.t\s+have\s+a\s+corresponding\b/,
      /\borphan\s+lines?\b|\borphaned\s+lines?\b/,
      // "every line ... matching header if there is one / if one exists"
      rx([String.raw`\bevery\s+(?:item\s+|invoice\s+)?line\b.*\bif\s+(?:there\s+is\s+one|one\s+exists?)\b`], ''),
      /\ball\s+(?:item\s+|invoice\s+)?lines?\b.*\b(?:attach|show|with)\s+(?:invoice\s+)?header\b/,
      // Right join phrasing
      /\bright\s+(?:join|outer)\b|\bright\s+joining\b/,
      /\blines?\s+(?:right\s+)?joined\s+to\s+(?:invoice\s+)?headers?\b/,
      /\bpreserve(?:d|ing)?\s+(?:all\s+)?(?:the\s+)?lines?\b/,
      /\bkeep\s+all\s+(?:the\s+)?lines?\b/,
      // "all invoice lines with/and their header details"  all-lines-first  RIGHT (rows 137-141)
      rx([String.raw`\ball\s+(?:invoice\s+)?lines?\s+(?:with|and)\s+(?:their\s+)?(?:invoice\s+|any\s+)?(?:matching\s+)?(?:header|invoice)\b`], ''),
      rx([String.raw`\ball\s+(?:invoice\s+)?lines?\s+(?:and|with)\s+(?:their\s+)?(?:invoice\s+)?header\s+(?:details?|info|data|columns?)\b`], ''),
      // "all lines information/data/details for each invoice"  all-lines with descriptor noun  RIGHT
      /\ball\s+(?:invoice\s+)?lines?\s+(?:information|info|data|details?|records?)\b/,
      /\ball\s+(?:invoice\s+)?line\s+(?:information|info|data|details?|records?)\b/,
      // "all lines for each invoice/invoice ID"  lines-first enumeration  RIGHT
      /\ball\s+(?:invoice\s+)?lines?\s+for\s+each\b/,
      /\ball\s+(?:invoice\s+)?line\s+(?:items?|entries|rows?)\s+for\b/,
      // "flag/label lines with no header as orphan records/lines" (rows 138-141)
      /\bflag\s+lines?\s+where\s+no\s+header\s+exists?\b/,
      /\blabel\s+lines?\b.*\bas\s+orphan\b/,
      /\blines?\s+where\s+no\s+(?:matching\s+)?(?:invoice\s+)?header\s+exists?\b/,
      /\bflag(?:ged)?\s+as\s+orphan\b/,
      /\bno\s+header\s+exists?\s+as\s+orphan\b/,
      rx([String.raw`\borphan\s+(?:lines?|records?)\b|\borphaned\s+(?:lines?|records?)\b`], ''),
      // "classify each as MATCHED or ORPHAN" / "whether it has a valid header or is an orphan"
      /\bclassif(?:y|ied)\s+(?:each\s+)?(?:as\s+)?(?:matched|orphan)\b/,
      /\bwhether\s+it\s+has\s+a\s+valid\s+header\s+or\s+is\s+an\s+orphan\b/,
      /\bline_status\b|\bhas\s+a\s+valid\s+header\b/,
    ];
    if (RIGHT_PATTERNS.some(function(rx){ return rx.test(t); })) joinType = 'RIGHT OUTER JOIN';
  }

  //  4. INNER JOIN semantic cues 
  // Signals: restrict to matching records ONLY, exclude unmatched rows
  // "only invoices that have [at least one/matching] line[s]"
  // "inner joined result", "where both records exist", "for matched invoices"
  if (!joinType) {
    var INNER_PATTERNS = [
      // Explicit "inner join" variants (joined, joining)
      /\binner\s+join(?:ed|ing)?\b/,
      // "only invoices/records that have at least one line"
      /\bonly\s+(?:invoices?|records?|rows?)\s+(?:that\s+)?(?:have|with)\s+at\s+least\s+one\s+line\b/,
      // "only for invoices that have matching lines"
      /\bonly\s+(?:for\s+)?(?:invoices?|records?|rows?)\s+(?:that\s+)?(?:have|with)\s+matching\b/,
      // "invoices that have matching lines / that have lines"
      rx([String.raw`\binvoices?\s+(?:that\s+)?(?:have|with)\s+(?:matching\s+|at\s+least\s+one\s+)?lines?\b`], ''),
      // "records that exist in both [tables]"
      /\b(?:records?|rows?)\s+(?:that\s+)?exist\s+in\s+both\b/,
      // "where a match exists in both"
      /\bwhere\s+(?:a\s+)?match\s+exists?\s+in\s+both\b/,
      // "where both records exist" / "where both the header and line records are present"
      /\bwhere\s+both\s+(?:the\s+)?(?:records?|rows?|header\s+and\s+line)\b/,
      /\bboth\s+(?:records?|rows?|entries?)\s+(?:are\s+)?(?:exist|present|available)\b/,
      /\bheader\s+and\s+line\s+records?\s+are\s+present\b/,
      // "both tables have a matching INVOICE_ID"
      /\bboth\s+tables?\s+have\s+a\s+matching\b/,
      // "inner joined result", "from the inner joined"
      /\binner\s+join(?:ed)?\s+result\b|\bfrom\s+the\s+inner\s+join(?:ed)?\b/,
      // "for matched invoices", "matched invoice records only"
      /\bfor\s+matched\s+(?:invoices?|records?)\b/,
      /\bmatched\s+(?:invoice|record|row)\s+records?\s+only\b|\bonly\s+matched\s+(?:invoice|record)s?\b/,
      // "where lines exist", "for invoices with matching line records"
      /\bwhere\s+lines?\s+exist\b/,
      /\bfor\s+invoices?\s+with\s+matching\s+line\s+records?\b/,
      // "only [show] invoices with lines" (intent to restrict)
      /\bonly\s+(?:show\s+)?invoices?\s+(?:that\s+)?(?:have|with)\s+lines?\b/,
      // "that have at least one line in the lines table"
      /\bthat\s+have\s+at\s+least\s+one\s+line\b/,
      // "exist in both tables"
      /\bexist\s+in\s+both\s+(?:tables?|ap_invoices_all|ap_invoice_lines_all)\b/,
      /\bfound\s+in\s+both\s+tables?\b/,
      // "where both"
      /\bwhere\s+both\b/,
      // "only matching", "matching only"
      rx([String.raw`\bonly\s+(?:the\s+)?matching\b|\bmatching\s+(?:records?|rows?|invoices?)\s+only\b`], ''),
      // "invoices that have lines" as aggregation context
      /\bfor\s+invoices?\s+that\s+have\s+lines?\b/,
      // "must have a matching / must exist"
      rx([String.raw`\bmust\s+(?:have\s+a?\s+)?matching\b|\bmust\s+exist\s+in\s+both\b`], ''),
      // CSV rows 77-82: "filter lines where [col] and join with headers" / ITEM lines with parent invoice
      /\bfilter\s+(?:the\s+)?lines?\s+where\b/,
      rx([String.raw`\b(?:item|freight|tax|miscellaneous)\s+(?:type\s+)?lines?\s+(?:with|and|joined?\s+to)\s+(?:their\s+)?(?:invoice\s+)?headers?\b`], ''),
      /\blines?\s+(?:of\s+type\b|where\s+line_type\b).*\bjoin(?:ed)?\s+with\s+(?:invoice\s+)?headers?\b/,
      rx([String.raw`\ball\s+(?:item|freight|tax)\s+(?:type\s+)?lines?\s+(?:from\s+ap_invoice_lines_all\s+)?with\s+(?:their\s+)?(?:parent\s+)?invoice\b`], ''),
      // Percentage/ratio calculations require both records  must be INNER JOIN
      rx([String.raw`\bwhat\s+percentage\b|\bhow\s+much\s+of\s+the\s+invoice\s+amount\b|\baccounts?\s+for\s+as\s+a\s+percentage\b`], ''),
      /\bpercentage\s+(?:of\s+(?:the\s+)?(?:invoice|total)|that\s+(?:the\s+)?line|contribution\b|share\b)/,
      /\bcompute\s+(?:the\s+)?percentage\b|\bcalculat\w+\s+(?:the\s+)?percentage\b/,
      /\bpercentage\s+(?:share|contribution)\s+of\s+(?:each\s+)?line\b/,
      /\bpercentage\s+contribution\s+to\s+(?:the\s+)?(?:parent\s+)?(?:invoice|total)\b/,
      /\bpct\s+of\s+(?:the\s+)?invoice(?:_amount)?\b/,
      rx([String.raw`\bshare\s+of\s+(?:the\s+)?(?:invoice|total)\b|\bshare\s+of\s+each\s+line\s+amount\b|\bproportion\s+of\s+(?:the\s+)?invoice\b`], ''),
      /\bline\s+amount\s+(?:as\s+a\s+)?(?:percentage|ratio|pct)\s+of\s+(?:the\s+)?invoice\b/,
      // Dual-table aggregation: metrics from BOTH header+line tables simultaneously  INNER (rows 110-113)
      /\binvoice\s+count\b.*\bline\s+count\b|\bline\s+count\b.*\binvoice\s+count\b/,
      rx([String.raw`\btotal\s+invoice\s+amount\b.*\btotal\s+line\s+amount\b|\btotal\s+line\s+amount\b.*\btotal\s+invoice\s+amount\b`], ''),
      /\baverage\s+line\s+amount\b|\bavg\s+line\s+amount\b/,
      /\bsums?\s+and\s+averages?\s+from\s+both\s+tables?\b/,
      /\bvendor[\s-](?:level\s+)?(?:summary|analytics|report)\b|\bvendor\s+analytics\s+report\b/,
      /\bfull\s+(?:vendor[\s-]level\s+)?(?:aggregate|summary)\s+from\s+joining\b/,
      /\bfor\s+invoices?\s+(?:that\s+)?(?:have|with)\s+lines?\b/,
      // "from matched records/invoices" (rows 85, 88)
      /\bfrom\s+matched\s+(?:invoices?|records?)\b/,
      // "ITEM lines and the associated invoice header" (row 82)
      /\b(?:item|freight|tax)\s+(?:type\s+)?lines?\s+(?:and|with)\s+(?:the\s+)?(?:associated|matching)\s+(?:invoice\s+)?headers?\b/,
      // Ranking/ordering by line amounts  lines MUST exist  INNER (rows 89-93)
      /\branked?\s+by\s+(?:their\s+)?(?:total\s+)?line\s+amounts?\b/,
      /\b(?:largest|highest|biggest)\s+(?:sum|total)\s+of\s+(?:the\s+)?line\s+amounts?\b/,
      /\bbased\s+on\s+sum\s+of\s+(?:their\s+)?line\s+amounts?\b/,
      // Balance / equality checks between line total and invoice header (rows 100-104)
      /\bbalance\s+exactly\b|\bperfectly\s+balanced\b|\bbalanced\s+invoices?\b/,
      /\bline\s+(?:total|sum)\s+equals?\s+(?:invoice|header)\b/,
      /\bsum\s+of\s+(?:the\s+)?lines?\s+of\s+type\b.*\bequal\s+to\b/,
      /\bitem\s+line\s+(?:total|sum)\s+equals?\s+(?:invoice|header)\b/,
      // "that have matching lines" standalone  catches "invoices from TABLE that have matching lines" (rows 2-6)
      /\bthat\s+have\s+matching\s+lines?\b/,
      // "ITEM type invoice lines with their invoice header"  "invoice" between "type" and "lines" (row 77)
      /\b(?:item|freight|tax)\s+type\s+invoice\s+lines?\s+with\s+(?:their\s+)?(?:invoice\s+)?header\b/,
      // "invoice lines of type ITEM along with / lines of type ITEM with"  reverse order (row 78)
      /\blines?\s+of\s+type\s+(?:item|freight|tax)\s+(?:along\s+with|with|and)\b/,
      // "joined with lines where LINE_AMOUNT is above 1000"  explicit right-side filter  INNER (rows 97-99)
      /\bjoined\s+with\s+lines?\s+where\b/,
      // "line amount exceeds/is greater than/is above N"  right-table column filter  INNER (rows 94-99)
      /\bline\s+amount\s+(?:is\s+)?(?:exceeds?|greater\s+than|above|is\s+above|is\s+over|over)\b/,
      /\bline_amount\s+(?:is\s+)?(?:greater\s+than|above|over|exceeds?)\b/,
      // "high-value lines above N"  filtering right side  INNER (row 99)
      /\bhigh[\s-]?value\s+lines?\b/,
    ];
    if (INNER_PATTERNS.some(function(rx){ return rx.test(t); })) joinType = 'INNER JOIN';
  }

  //  5. LEFT OUTER JOIN semantic cues 
  // Signals: preserve ALL from left (header/invoices) even when no matching lines
  // "all invoices even if no lines", "include headers without lines"
  // "keep invoices that have no lines", "show null where no line exists"
  if (!joinType) {
    var LEFT_PATTERNS = [
      // "even if [they/some invoices] don't have [any] lines / no lines yet"
      rx([String.raw`\beven\s+if\s+(?:they\s+)?(?:don.t\s+have|have\s+no)\s+(?:any\s+)?(?:lines?|line\s+details?)\b`], ''),
      /\beven\s+if\s+(?:some\s+)?invoices?\s+have\s+no\s+lines?\b/,
      // "keeping invoices that have no lines"
      /\bkeeping\s+invoices?\s+(?:that\s+)?(?:have\s+no|with\s+no|without)\s+lines?\b/,
      // "include[ing] [invoice headers / invoices] [with no / without] [any] lines"
      rx([String.raw`\bincluding?\s+(?:invoice\s+)?(?:headers?|invoices?)\s+(?:with\s+no|without|that\s+have\s+no)\s+(?:any\s+)?(?:line|lines?)\b`], ''),
      rx([String.raw`\binclude\s+(?:invoices?|headers?)\s+(?:with\s+no|without)\s+(?:any\s+)?(?:lines?|line\s+details?)\b`], ''),
      // "show[ing] [null / zero / 0] where no line exists / for invoices without lines"
      /\bshow(?:ing)?\s+(?:null|zero|0)\s+(?:description\s+|amount\s+)?where\s+no\s+line\s+exists?\b/,
      /\bdefaulting\s+to\s+zero\s+if\s+no\s+lines?\s+exist\b/,
      /\bshow\s+0\s+for\s+invoices?\s+(?:with\s+no|without)\s+lines?\b/,
      // "keep[ing] all [approved] invoices [even] without lines"
      /\bkeep(?:ing)?\s+(?:all\s+)?(?:approved\s+)?invoices?\s+(?:even\s+)?without\s+(?:matching\s+)?lines?\b/,
      /\bkeep(?:ing)?\s+(?:all\s+)?(?:approved\s+)?invoices?\s+even\s+(?:if|without)\b/,
      // "all invoices even if [no lines / unmatched]"
      /\ball\s+(?:approved\s+)?invoices?\s+even\s+if\b/,
      /\ball\s+(?:invoice\s+)?headers?\s+(?:must\s+)?appear\s+even\s+without\b/,
      // "invoices with no ITEM lines should still appear"
      /\bshould\s+still\s+appear\b/,
      // "show null line columns for invoices with no ITEM lines"
      /\bshow\s+null\s+(?:line\s+)?columns?\s+for\s+invoices?\b/,
      // "include headers without any line details"
      /\bheaders?\s+without\s+(?:any\s+)?line\s+details?\b/,
      // "all invoices and include those with no lines"
      rx([String.raw`\ball\s+(?:ap\s+)?invoices?\s+(?:and\s+)?(?:include\s+)?those\s+(?:that\s+)?(?:have\s+)?no\s+lines?\b`], ''),
      // "invoices with zero lines" / "invoices with no corresponding lines"
      /\binvoices?\s+with\s+(?:zero|no|0)\s+lines?\b/,
      /\binvoices?\s+(?:that\s+)?have\s+(?:zero|no)\s+lines?\b/,
      // "no children", "missing from AP_INVOICE_LINES_ALL", "zero lines associated"
      /\bno\s+children\s+in\b|\bmissing\s+from\s+ap_invoice_lines_all\b/,
      /\bzero\s+lines?\s+associated\s+with\b/,
      // "include invoices that have no lines [at all]"
      /\binclud(?:e|ing)\s+invoices?\s+(?:that\s+)?(?:have\s+)?no\s+lines?\b/,
      // Generic LEFT indicators
      /\bincluding\s+(?:those\s+)?(?:that\s+)?(?:have\s+)?no\s+(?:lines?|matching)\b/,
      /\bleft\s+(?:outer\s+)?join\b/,
    ];
    if (LEFT_PATTERNS.some(function(rx){ return rx.test(t); })) joinType = 'LEFT OUTER JOIN';
  }

  //  6. Fusion header+detail default (no semantic cues detected) 
  // For known Oracle Fusion header+detail table pairs, LEFT OUTER is the best-practice default
  if (!joinType) {
    var FUSION_HDR_DTL = {
      'AP_INVOICES_ALL':              'AP_INVOICE_LINES_ALL',
      'GL_JE_HEADERS':                'GL_JE_LINES',
      'PO_HEADERS_ALL':               'PO_LINES_ALL',
      'PO_REQUISITION_HEADERS_ALL':   'PO_REQUISITION_LINES_ALL',
    };
    var lTbl = S.sources.length >= 1 ? S.sources[0].table : null;
    var rTbl = S.sources.length >= 2 ? S.sources[1].table : null;
    if (lTbl && rTbl && FUSION_HDR_DTL[lTbl] === rTbl) {
      joinType = 'LEFT OUTER JOIN';
    }
  }

  //  7. Absolute fallback 
  if (!joinType) joinType = 'LEFT OUTER JOIN';

  // Determine right source
  var rightSrc = (() => { if (mentioned.length >= 2) { return mentioned[1]; } if (S.sources.length >= 2) { return S.sources[1]; } return null; })();
  var leftSrc  = (() => { if (mentioned.length >= 1) { return mentioned[0]; } if (S.sources.length >= 1) { return S.sources[0]; } return null; })();

  if (!rightSrc) { notify('Add at least 2 sources first, then describe the join.','err'); return; }

  var leftAlias  = leftSrc  ? (leftSrc.alias||leftSrc.table)   : 'T1';
  var rightAlias = rightSrc ? (rightSrc.alias||rightSrc.table) : 'T2';

  // Build condition
  var conds = [];
  if (resolvedKey) {
    conds.push({ id:uid(), l:leftAlias+'.'+resolvedKey, op:'=', r:rightAlias+'.'+resolvedKey });
  } else {
    // Auto-suggest from FUSION_DB
    var sugg = fusionJoinSuggest(leftSrc.table, rightSrc.table);
    if (sugg.length) {
      conds.push({ id:uid(), l:leftAlias+'.'+sugg[0].lc, op:'=', r:rightAlias+'.'+sugg[0].rc });
      resolvedKey = sugg[0].lc;
    } else {
      conds.push({ id:uid(), l:leftAlias+'.'+'/* key */', op:'=', r:rightAlias+'.'+'/* key */' });
    }
  }

  S.joins.push({ id:uid(), type:joinType, rightId:rightSrc.id, conds:conds });
  document.getElementById(inputId).value = '';
  refreshCard('joins'); refreshSQL();
  notify('JOIN added  '+joinType+' on '+(resolvedKey||'key'), 'ok');
}

//  NL  FILTER 
// --- helpers extracted from nlApplyToFilterInput (behavior-identical) ---
function nlApplyToFilterInput_p1(added, inputId){
if (added > 0) {
    document.getElementById(inputId).value = '';
    refreshCard('filter'); refreshSQL();
    notify(added+' filter'+(added>1?'s':'')+' added', 'ok');
  } else {
    notify('No filter detected. Try: "show only active employees" or "amount greater than 1000" or "last 6 months"','err');
  }
}

function nlApplyToFilterInput(inputId) {
  var text = (document.getElementById(inputId)||{}).value;
  if (!text || !text.trim()) return;
  text = text.trim();
  var t  = ' ' + text.toLowerCase().replaceAll(/[^\w\s.]/g,' ') + ' ';
  var tU = t.replaceAll('_',' ');
  var added = 0;

  //  Date BETWEEN in natural language 
  // Patterns: "invoice date between 1st jan 2020 and 1st jan 2025"
  //           "invoice date in between 1st jan 2020 to 1st jan 2025"
  //           "between 1st jan 2020 and 1st jan 2025"
  //           "from 1st jan 2020 to 1st jan 2025"
  var dateBetweenHandled = false;
  (function(){
    // Collect all date strings from the input
    var dateMatches = [];
    var dm;
    NL_DATE_STR_RE.lastIndex = 0;
    while ((dm = NL_DATE_STR_RE.exec(text)) !== null) dateMatches.push(dm[0]);
    if (dateMatches.length < 2) return;  // need at least two dates for BETWEEN

    // Detect the column being filtered
    var dateCol = nlColFromText(text);
    // If not found via explicit cols, try common date column names in sources
    if (!dateCol) {
      var colCandidates = ['INVOICE_DATE','CREATION_DATE','CHECK_DATE','TRANSACTION_DATE',
                           'GL_DATE','ACCOUNTING_DATE','EFFECTIVE_START_DATE','PAYMENT_DATE'];
      for (let cc of colCandidates){
        if (!dateCol && rx([String.raw``, cc.replaceAll('_','[_ ]'), String.raw``], 'i').test(text)) {
          dateCol = nlResolveColInSources(cc);
        }
      }
    }
    // Fallback: look for any word ending in "date" near the between keyword
    if (!dateCol) {
      var dColM = text.match(/\b(\w+_?date)\b/i);
      if (dColM) dateCol = nlResolveColInSources(dColM[1].toUpperCase());
    }
    if (!dateCol) {
      // Use primary entity's dateCol or CREATION_DATE
      dateCol = 'CREATION_DATE';
      dateCol = nlResolveColInSources(dateCol);
    }

    var d1 = nlParseDate(dateMatches[0]);
    var d2 = nlParseDate(dateMatches[1]);
    S.filters.push({
      id:uid(), logic:'AND', clause:'WHERE', srcId:'',
      col: dateCol + ' BETWEEN ' + d1 + ' AND ' + d2,
      op:'', val:''
    });
    added++;
    dateBetweenHandled = true;
  })();

  if (dateBetweenHandled) {
    document.getElementById(inputId).value = '';
    refreshCard('filter'); refreshSQL();
    notify(added+' date filter'+(added>1?'s':'')+' added', 'ok');
    return;
  }

  //  Direct SQL-style expressions: col op value 
  // Uses strict word boundaries so "IN" doesn't match inside "invoices"
  // e.g. "invoice_id='INV123'"  "amount > 1000"  "status != 'CANCELLED'"
  var exprRe = rx([String.raw`([\w.]+)\s*(!=|<>|>=|<=|>|<|=|\bLIKE\b|\bIS\s+NOT\s+NULL\b|\bIS\s+NULL\b|\bNOT\s+LIKE\b|\bIN\b)\s*([^\s][^]*?)?(?=\s+\bAND\b|\s+\bOR\b|$)`], 'gi');
  var logicRe = /\bAND\b|\bOR\b/gi;
  var exprMatch;
  var exprMatches = [];
  while ((exprMatch = exprRe.exec(text)) !== null) {
    var rawCol = exprMatch[1].trim();
    var rawOp  = exprMatch[2].trim().replaceAll(/\s+/g,' ').toUpperCase();
    var rawVal = (exprMatch[3]||'').trim().replace(/;$/,'').trim();

    // Resolve column  try to find in loaded sources, then explicit cols
    var resolvedCol = rawCol;
    var rawColUpper = rawCol.replaceAll(/\s+/g,'_').toUpperCase();
    // If col already has alias prefix (e.g. S1.INVOICE_ID) keep as-is
    if (!rawCol.includes('.')) {
      // Check if it matches a known column in sources
      var foundInSrc = false;
      for (let src of S.sources){
        if (!foundInSrc) {
          let c = src.columns.find(function(c){ return c.name.toUpperCase() === rawColUpper; });
          if (c) { resolvedCol = (src.alias||src.table)+'.'+c.name; foundInSrc = true; }
        }
      }
      // If not found in sources, check NL_EXPLICIT_COLS for alias
      if (!foundInSrc) {
        for (let ec of NL_EXPLICIT_COLS){
          if (!foundInSrc && (ec.col.toUpperCase() === rawColUpper ||
              ec.words.some(function(w){ return w.replaceAll('_','').toUpperCase() === rawCol.replaceAll('_','').toUpperCase(); }))) {
            resolvedCol = nlResolveColInSources(ec.col) || ec.col;
            foundInSrc = true;
          }
        }
      }
    }

    // Normalise value  ensure strings are quoted, NULL/SYSDATE left bare
    var finalVal = rawVal;
    var noVal = rawOp === 'IS NULL' || rawOp === 'IS NOT NULL';
    if (!noVal && finalVal) {
      var isAlreadyQuoted = /^'.*'$/.test(finalVal) || /^".*"$/.test(finalVal);
      var isBareWord = rx([String.raw`^[A-Za-z_][A-Za-z0-9_]*$`], '').test(finalVal) && !['NULL','SYSDATE','TRUE','FALSE'].includes(finalVal.toUpperCase());
      if (!isAlreadyQuoted && Number.isNaN(Number.parseFloat(finalVal)) && !finalVal.toUpperCase().startsWith('SYSDATE') && !finalVal.includes('(') && isBareWord) {
        finalVal = "'"+finalVal.toUpperCase()+"'";
      }
      // Normalise double-quotes  single-quotes
      if (/^".*"$/.test(finalVal)) finalVal = "'"+finalVal.slice(1,-1)+"'";
    }

    exprMatches.push({ col:resolvedCol, op:rawOp, val:noVal ? '' : finalVal });
  }

  // Detect AND/OR logic between expressions
  if (exprMatches.length > 0) {
    var logics = [];
    var lm;
    logicRe.lastIndex = 0;
    while ((lm = logicRe.exec(text)) !== null) logics.push(lm[0].toUpperCase());
    for (let [i, ex] of exprMatches.entries()){
      let logic = i === 0 ? 'AND' : (logics[i-1] || 'AND');
      S.filters.push({ id:uid(), logic:logic, clause:'WHERE', srcId:'', col:ex.col, op:ex.op, val:ex.val });
      added++;
    }
  }

  //  Business language / NL patterns (only if no direct expressions found) 
  if (added === 0) {
  // Status / business condition maps
  for (let sm of NL_STATUS_MAPS){
    if (nlHasPhrase(t, tU, sm.words)) {
      for (let f of sm.filters){
        let fullCol = nlResolveColInSources(f.col);
        S.filters.push({ id:uid(), logic:'AND', clause:'WHERE', srcId:'', col:fullCol, op:f.op, val:f.val });
        added++;
      }
    }
  }

  // Date filters
  for (let de of NL_DATE_EXPRS){
    if (nlHasPhrase(t, tU, de.words)) {
      let datecol = 'CREATION_DATE';
      for (let src of S.sources){
        let td = FUSION_DB.tables[src.table];
        if (td && td.dateEffective) datecol = 'EFFECTIVE_START_DATE';
        else if (td && td.dateCol) datecol = td.dateCol;
      }
      let fullCol = nlResolveColInSources(datecol);
      if (de.op) {
        S.filters.push({ id:uid(), logic:'AND', clause:'WHERE', srcId:'', col:fullCol, op:de.op, val:de.expr });
      } else {
        S.filters.push({ id:uid(), logic:'AND', clause:'WHERE', srcId:'', col:fullCol+' '+de.expr, op:'', val:'' });
      }
      added++;
    }
  }

  // Numeric comparison (greater than, less than, between)
  for (let p of NL_COND_OPS){
    let m = text.match(p.re);
    if (!m) continue;
    let rawVal = (m[1]||'').trim().replaceAll(',','');
    let numVal = Number.parseFloat(rawVal);
    let val = Number.isNaN(numVal) ? "'"+rawVal.toUpperCase()+"'" : rawVal;
    if (p.op==='LIKE') val = "'%"+rawVal.toUpperCase()+"%'";
    let col = nlColFromText(text);
    if (!col) {
      for (let src of S.sources){
        if (!col) { let nc = src.columns.find(function(c){ return c.dataType==='NUMBER'; });
          if (nc) col = (src.alias||src.table)+'.'+nc.name; }
      }
    }
    if (!col) col = 'AMOUNT';
    S.filters.push({ id:uid(), logic:'AND', clause:'WHERE', srcId:'', col:col, op:p.op, val:val });
    added++;
  }

  // BETWEEN N and M
  var betM = text.match(/\bbetween\s+([0-9,.]+)\s+and\s+([0-9,.]+)/i);
  if (betM) {
    var bcol = nlColFromText(text) || 'AMOUNT';
    S.filters.push({ id:uid(), logic:'AND', clause:'WHERE', srcId:'', col:bcol+' BETWEEN '+betM[1].replaceAll(',','')+' AND '+betM[2].replaceAll(',',''), op:'', val:'' });
    added++;
  }

  // "status is X"
  var stM = text.match(/\bstatus\s+(?:is\s+|=\s*)?['"]?([a-z]\w*)['"]?/i);
  if (stM && !['null','not'].includes(stM[1].toLowerCase())) {
    var scol = nlResolveColInSources('STATUS');
    S.filters.push({ id:uid(), logic:'AND', clause:'WHERE', srcId:'', col:scol, op:'=', val:"'"+stM[1].toUpperCase()+"'" });
    added++;
  }

  } // end: if (added === 0) NL branch

  nlApplyToFilterInput_p1(added, inputId);
}

//  NL  GROUP BY + AGGREGATE 
// --- helpers extracted from nlApplyToGroupByInput (behavior-identical) ---
function nlApplyToGroupByInput_p1(added, gb, inputId){
if (added > 0) {
    S.groupBy = gb;
    document.getElementById(inputId).value = '';
    refreshCard('groupby'); refreshSQL();
    notify(added+' expression'+(added>1?'s':'')+' added to Group By', 'ok');
  } else {
    notify('No grouping detected. Try: "group by department" or "sum invoice amount by supplier"','err');
  }
}

function nlApplyToGroupByInput(inputId) {
  var text = (document.getElementById(inputId)||{}).value;
  if (!text || !text.trim()) return;
  text = text.trim();
  var t  = ' ' + text.toLowerCase().replaceAll(/[^\w\s.]/g,' ') + ' ';
  var tU = t.replaceAll('_',' ');
  var gb = S.groupBy || { dims:[], aggs:[], having:[] };
  var added = 0;

  // Detect GROUP BY dimensions
  for (let g of NL_GROUP_HINTS){
    if (nlHasPhrase(t, tU, g.words)) {
      let col = g.raw ? g.col : nlResolveColInSources(g.col);
      if (!gb.dims.some(function(d){ return d.col===col || d.col===g.col; })) {
        gb.dims.push({ id:uid(), col:col, alias:g.label });
        added++;
      }
    }
  }

  // Detect aggregate function
  var aggFn = null;
  for (let a of NL_AGG){ if (!aggFn && nlHasPhrase(t, tU, a.words)) aggFn = a.fn; }

  if (aggFn) {
    var aggColName = null;
    for (let ec of NL_EXPLICIT_COLS){ if (!aggColName && nlHasPhrase(t, tU, ec.words)) aggColName = ec.col; }
    if (!aggColName) { for (let h of NL_COL_HINTS.filter(function(h){ return h.num; })){
      if (!aggColName && nlHasPhrase(t, tU, h.words)) aggColName = h.col;
    } }
    var fullAggCol = aggColName ? nlResolveColInSources(aggColName) : '';
    if (!fullAggCol && aggFn !== 'COUNT') {
      for (let src of S.sources){
        if (!fullAggCol){ let nc = src.columns.find(function(c){ return c.dataType==='NUMBER'; });
          if (nc) fullAggCol = (src.alias||src.table)+'.'+nc.name; }
      }
    }
    if (aggFn === 'COUNT' && !fullAggCol) fullAggCol = '*';
    var al = aggFn+(fullAggCol && fullAggCol!=='*' ? '_'+fullAggCol.split('.').pop() : '_TOTAL');
    gb.aggs.push({ id:uid(), fn:aggFn, col:fullAggCol||'', val:'', alias:al });
    added++;
  }

  nlApplyToGroupByInput_p1(added, gb, inputId);
}

// Tracks whether the open NL modal was launched from the landing screen's "NL Query"
// card, so closing it without connecting can send the user back there (see closeNLModal).
var _nlFromLanding = false;

// Shared show/hide so the browser Back button and the programmatic "return to
// landing" path (closeNLModal) both end up in the exact same state.
function showAppLayout() {
  document.getElementById('landing-screen').style.display = 'none';
  document.getElementById('app-layout').style.display = '';
  document.getElementById('home-btn').style.display = '';
}
function showLandingScreen() {
  document.getElementById('app-layout').style.display = 'none';
  document.getElementById('landing-screen').style.display = '';
  document.getElementById('nl-modal').classList.remove('open');
  document.getElementById('home-btn').style.display = 'none';
}
// Explicit, always-reliable way back to the landing screen (doesn't depend on the
// browser's own Back button, which can behave inconsistently with file:// pages).
function goHome(){
  showLandingScreen();
  if (location.hash) { try { history.replaceState(null, '', location.pathname + location.search); } catch(e){ console.debug('sqg: replaceState unsupported', e); } }
}

function chooseLandingMode(mode) {
  showAppLayout();
  try { if (location.hash !== '#app') history.pushState({view:'app'}, '', '#app'); } catch(e){ console.debug('sqg: pushState unsupported', e); }
  if (mode === 'nlquery') { _nlFromLanding = true; openNLModal(); }
}
window.addEventListener('popstate', function(){
  if (location.hash === '#app') showAppLayout(); else showLandingScreen();
});

//  Modal open / close
function openNLModal() {
  document.getElementById('nl-modal').classList.add('open');
  nlRenderModal();
}
// Keep the modal's "AI Generate" label in sync with connection state.
function nlSyncAiBtn(){
  var b = document.getElementById('nl-ai-btn'); if(!b) return;
  b.innerHTML = aiIsDemo() ? ' AI Generate (demo)' : ' AI Generate';
}
// Gate the NL Query modal behind connection: show the connect prompt first; once an
// API key (or demo mode) is connected, reveal the generator with no connect control.
function nlRenderModal(){
  var conn  = document.getElementById('nl-conn');
  var gate  = document.getElementById('nl-gate');
  var ready = document.getElementById('nl-ready');
  if (!gate || !ready) return;
  var real = !!(S.apiKey && S.apiKey.trim());
  var demo = aiIsDemo();

  if (real || demo) {
    // ---- CONNECTED: show the generator, header shows status only (no Connect button) ----
    gate.style.display = 'none';
    ready.style.display = 'block';
    if (conn) {
      conn.innerHTML = real
        ? '<span style="color:#22c55e;font-weight:700;font-size:11px"> API connected</span><button class="btn btn-xs btn-danger" id="nl-conn-x" title="Disconnect" style="padding:0 7px">&#x2715;</button>'
        : '<span style="color:var(--amber,#f59e0b);font-weight:700;font-size:11px"> Demo mode</span><button class="btn btn-xs btn-danger" id="nl-conn-x" title="Exit demo mode" style="padding:0 7px">&#x2715;</button>';
      var xb = document.getElementById('nl-conn-x');
      if (xb) xb.onclick = function(){ if(aiIsDemo()){ nlSetDemoMode(false); } else { nlSetApiKey(''); } nlRenderModal(); };
    }
    nlSyncAiBtn();
    setTimeout(function(){ var t=document.getElementById('nl-input'); if(t) t.focus(); }, 80);
  } else {
    // ---- NOT CONNECTED: show the connect gate only ----
    ready.style.display = 'none';
    if (conn) conn.innerHTML = '';   // no Connect button in the header  the gate handles it
    gate.style.display = 'block';
    gate.innerHTML =
      '<div style="text-align:center;padding:16px 8px 10px">'+
        '<svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#06b6d4" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="margin-bottom:8px"><path d="M21 2l-2 2m-7.61 7.61a5.5 5.5 0 1 1-7.778 7.778 5.5 5.5 0 0 1 7.777-7.777zm0 0L15.5 7.5m0 0l3 3L22 7l-3-3m-3.5 3.5L19 4"></path></svg>'+
        '<div style="font-size:15px;font-weight:700;color:var(--text);margin-bottom:5px">Connect to use Natural Language  SQL</div>'+
        '<div style="font-size:12px;color:var(--text2);margin:0 auto 16px;max-width:520px;line-height:1.6">This feature uses Claude. Paste your Anthropic API key to connect  it is kept for this session only and never saved to disk. No key? <b>Try demo mode</b> to explore with the built-in offline engine.</div>'+
      '</div>'+
      '<div style="display:flex;gap:6px;align-items:center;max-width:560px;margin:0 auto">'+
        '<input id="nl-conn-key" type="password" class="cell-inp" autocomplete="off" placeholder="Paste Anthropic API key (sk-ant-)" style="flex:1;font-size:12px">'+
        '<button class="btn btn-sm" id="nl-conn-save" style="background:rgba(34,197,94,.15);color:#22c55e;border-color:rgba(34,197,94,.4);white-space:nowrap;font-weight:600">Connect</button>'+
      '</div>'+
      '<div style="display:flex;gap:14px;align-items:center;justify-content:center;margin-top:12px">'+
        '<button class="btn btn-sm" id="nl-conn-demo" style="background:rgba(245,158,11,.15);color:var(--amber,#f59e0b);border-color:rgba(245,158,11,.4)"> Try demo mode</button>'+
        '<a href="https://console.anthropic.com/settings/keys" target="_blank" rel="noopener" style="font-size:11px;color:#58a6ff;text-decoration:underline">Get a key</a>'+
      '</div>';
    var key = document.getElementById('nl-conn-key');
    var save = document.getElementById('nl-conn-save');
    var dm = document.getElementById('nl-conn-demo');
    if (save) save.onclick = async function(){
      var v=(key&&key.value||'').trim();
      if(!v){ if(key){ key.focus(); } return; }
      save.textContent = ' Validating'; save.disabled = true;
      var ok = await nlValidateApiKey(v);
      save.textContent = 'Connect'; save.disabled = false;
      if(!ok) return; // nlValidateApiKey already showed the error - stay on the connect gate
      nlSetApiKey(v); nlRenderModal();
    };
    if (key)  key.addEventListener('keydown', function(e){ if(e.key==='Enter' && save) save.onclick(); });
    if (dm)   dm.onclick = function(){ nlSetDemoMode(true); nlRenderModal(); };
    setTimeout(function(){ if(key) key.focus(); }, 80);
  }
}
function closeNLModal() {
  document.getElementById('nl-modal').classList.remove('open');
  // Came from the landing screen's NL Query card and left without connecting an API
  // key or demo mode -> send them back to the landing screen instead of stranding
  // them in the Custom Form builder they never chose. Uses the same direct, history-
  // independent path as goHome() (see its comment for why history.back() isn't used).
  if (_nlFromLanding && !aiConnected()) {
    goHome();
  }
  _nlFromLanding = false;
}

// ==================== LIVE DB: connections manager + browser ====================
// Talks to the local Python bridge (db-bridge/app.py). Read-only metadata only.
// Demo connections work fully client-side (browse the built-in Fusion KB, no bridge).
var _liveDBLast = null, _dbTab = 'wallet', _walletToken = null;
// Where a picked live table should land: null = new source; else {kind:'fromMember', srcId, ftId}
var _liveDBTarget = null;
// Open the Live DB browser to fill a specific target (a derived source base or a subquery FROM member).
function openLiveDBFor(target){ _liveDBTarget = target; openDbConn(); }
var _activeConn = { name:'', kind:'demo', schema:'' };
// Live-DB table suggestions for a Source "Table" field, driven by the Module
// dropdown's "Live DB" option. Aggregates tables from ALL saved live connections.
var _liveTblTimer = null;
function fillLiveDBTables(srcId, tblInp, q){
  var dlId = 'dl-fusion-'+srcId;
  var dl = document.getElementById(dlId);
  if(!dl){ dl = document.createElement('datalist'); dl.id = dlId; document.body.appendChild(dl); }
  tblInp.setAttribute('list', dlId);
  fetchT(dbBridgeUrl()+'/connections', {}, 8000).then(function(r){return r.json();}).then(function(j){
    var conns = (j && j.connections) || [];
    if(!conns.length){ dl.innerHTML = '<option value="">'; return; }
    var seen = {}, opts = [];
    conns.forEach(function(cn){
      var qs = ['conn='+encodeURIComponent(cn.name)];
      if(q) qs.push('q='+encodeURIComponent(q));
      fetchT(dbBridgeUrl()+'/tables?'+qs.join('&'), {}, 8000).then(function(r){return r.json();}).then(function(jj){
        if(jj && jj.status==='ok' && Array.isArray(jj.tables)){
          jj.tables.slice(0,300).forEach(function(t){
            var nm = (t.owner && t.owner!=='DEMO') ? (t.owner+'.'+t.table) : t.table;
            if(nm && !seen[nm]){ seen[nm]=1; opts.push('<option value="'+String(nm).replaceAll('"','&quot;')+'">'); }
          });
          dl.innerHTML = opts.join('');
        }
      }).catch(function(){});
    });
  }).catch(function(){ dl.innerHTML = '<option value="">'; });
}
function liveTableSuggest(inp){
  var id = inp.id.replace('fusion-tbl-','');
  var modSel = document.getElementById('fusion-mod-'+id);
  if(!modSel || modSel.value!=='__livedb__') return;
  clearTimeout(_liveTblTimer);
  _liveTblTimer = setTimeout(function(){ fillLiveDBTables(id, inp, (inp.value||'').trim()); }, 300);
}
document.addEventListener('input', function(e){
  var t = e.target;
  if(t && t.id && t.id.indexOf('fusion-tbl-')===0){ liveTableSuggest(t); }
});
function dbBridgeUrl(){ return (localStorage.getItem('sqg_bridge_url')||'http://localhost:8788').replace(rx([String.raw`\/+$`], ''),''); }
// fetch with a hard timeout so the UI never spins forever if the bridge/DB hangs
function fetchT(url, opts, ms){
  opts = opts || {};
  var ctrl = new AbortController();
  var id = setTimeout(function(){ ctrl.abort(); }, ms || 30000);
  opts.signal = ctrl.signal;
  return fetch(url, opts).finally(function(){ clearTimeout(id); });
}
function isTimeout(e){ return e && (e.name==='AbortError'); }
function getDemoConns(){ try { return JSON.parse(localStorage.getItem('sqg_demo_conns')||'[]'); } catch(e){ console.debug('sqg: demo store reset', e); return []; } }
function saveDemoConns(l){ localStorage.setItem('sqg_demo_conns', JSON.stringify(l)); }

//  Connections manager
// #dbconn-panel is a single DOM node authored inline on the landing screen. Opening the
// modal here just moves that same node (and its live state - values, listeners) into the
// modal box; closing moves it back. No duplicated markup/ids, so the panel always shows
// identical, in-sync data whether it's embedded on landing or popped up from Custom Form.
function openDbConn(){
  var panel = document.getElementById('dbconn-panel');
  var box = document.getElementById('dbconn-modal-box');
  if (panel.parentElement !== box) box.appendChild(panel);
  document.getElementById('dbconn-modal').style.display = 'flex';
  dbConnTab(_dbTab);
  dbConnRefreshList();
}
function closeDbConn(){
  document.getElementById('dbconn-modal').style.display = 'none';
  var panel = document.getElementById('dbconn-panel');
  var slot = document.getElementById('landing-dbconn-slot');
  if (panel.parentElement !== slot) slot.appendChild(panel);
}

function dbConnTab(which){
  if(which) _dbTab = which;
  var demo = document.getElementById('dbf-demo').checked;
  document.getElementById('dbtab-basic').classList.toggle('on', _dbTab==='basic');
  document.getElementById('dbtab-wallet').classList.toggle('on', _dbTab==='wallet');
  document.getElementById('dbf-wallet-block').style.display = (!demo && _dbTab==='wallet') ? 'block':'none';
  document.getElementById('dbf-basic-block').style.display  = (!demo && _dbTab==='basic')  ? 'block':'none';
  // credentials hidden for demo
  document.getElementById('dbf-creds-block').style.display  = demo ? 'none':'block';
}

function dbConnUploadWallet(input){
  var f = input.files && input.files[0]; if(!f) return;
  var lbl = document.getElementById('dbf-wallet-name');
  lbl.textContent = f.name + ' — uploading…';
  var fd = new FormData(); fd.append('wallet', f);
  fetchT(dbBridgeUrl()+'/wallet/services', {method:'POST', body:fd}, 20000).then(function(r){return r.json();}).then(function(j){
    if(!j || j.status!=='ok'){ lbl.textContent = 'Upload failed: '+((j&&j.error)||''); return; }
    _walletToken = j.token;
    var svcs = j.services||[];
    document.getElementById('dbf-service-dl').innerHTML = svcs.map(function(s){ return '<option value="'+s+'">'; }).join('');
    lbl.textContent = f.name + ' — ' + svcs.length + ' service(s) found';
    var svcInput = document.getElementById('dbf-service');
    if(svcs.length && !svcInput.value){ svcInput.value = svcs.find(function(s){return /_low$/i.test(s);}) || svcs[0]; }
  }).catch(function(){ lbl.textContent = 'Cannot reach bridge — start db-bridge/app.py first.'; });
}

function dbConnSave(){
  var name = (document.getElementById('dbf-name').value||'').trim();
  var msg  = document.getElementById('dbf-msg');
  if(!name){ msg.style.color='#ef4444'; msg.textContent='Enter a connection name.'; return; }
  var demo = document.getElementById('dbf-demo').checked;
  if(demo){
    var list = getDemoConns().filter(function(c){ return c.name!==name; });
    list.push({ name:name, kind:'demo', target:'mock (demo)', env:'DEV',
                status:'ok', schema:'', readonly:true });
    saveDemoConns(list);
    msg.style.color='var(--green)'; msg.textContent='✔ Demo connection saved.';
    dbConnRefreshList(); return;
  }
  var fd = new FormData();
  fd.append('name', name); fd.append('kind', _dbTab); fd.append('demo','false');
  fd.append('username', document.getElementById('dbf-user').value);
  fd.append('password', document.getElementById('dbf-pass').value);
  fd.append('readonly', 'true');
  if(_dbTab==='wallet'){
    fd.append('service', document.getElementById('dbf-service').value);
    if(_walletToken) fd.append('walletToken', _walletToken);
  } else {
    fd.append('host', document.getElementById('dbf-host').value);
    fd.append('port', document.getElementById('dbf-port').value);
    fd.append('service', document.getElementById('dbf-bservice').value);
  }
  msg.style.color='var(--text3)'; msg.textContent='Connecting & saving… (up to ~20s)';
  fetchT(dbBridgeUrl()+'/connections', {method:'POST', body:fd}, 35000).then(function(r){return r.json();}).then(function(j){
    var okConn = j && j.status==='ok' && (!j.connection || j.connection.status==='ok');
    if(okConn){ msg.style.color='var(--green)'; msg.textContent='✔ Connected & saved.'; _walletToken=null; }
    else { msg.style.color='#ef4444'; msg.textContent='Saved, but connection test failed: '+((j&&j.error)||'see status'); }
    dbConnRefreshList();
  }).catch(function(e){
    msg.style.color='#ef4444';
    msg.textContent = isTimeout(e)
      ? 'Timed out reaching the database. The DB host is likely blocked by a firewall or needs VPN — the wallet/service is fine, the network path isn\'t.'
      : 'Cannot reach bridge at '+dbBridgeUrl()+' — start db-bridge/app.py.';
  });
}

function dbConnRefreshList(){
  var box = document.getElementById('dbconn-list');
  var st  = document.getElementById('dbconn-bridge-status');
  var demo = getDemoConns();
  var render = function(bridgeConns, bridgeOk){
    st.style.color = bridgeOk ? 'var(--green)' : '#ef4444';
    st.textContent = bridgeOk ? '● bridge connected' : '● bridge offline (demo still works)';
    var all = demo.concat(bridgeConns||[]);
    if(!all.length){ box.innerHTML='<div style="font-size:11px;color:var(--text3)">No saved connections yet.</div>'; return; }
    var esc = function(v){ return String(v==null?'':v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;'); };
    var TPL = 'display:grid;grid-template-columns:34% 13% 28% 10% 15%;align-items:center;gap:4px';
    var cell = 'overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;padding-right:6px';
    box.innerHTML = '<div style="font-size:11px">'+
      '<div style="'+TPL+';padding:3px 4px;color:var(--text3);border-bottom:1px solid var(--border);font-weight:600">'+
        '<div>Name</div><div>Type</div><div>Target</div><div>Status</div><div></div>'+
      '</div>'+
      all.map(function(c){
        var badge = c.status==='ok'
          ? '<span style="background:#16a34a;color:#fff;border-radius:10px;padding:1px 8px;font-size:10px">ok</span>'
          : '<span style="background:#ef4444;color:#fff;border-radius:10px;padding:1px 8px;font-size:10px">err</span>';
        return '<div class="livedb-row" style="'+TPL+';padding:5px 4px;border-bottom:1px solid var(--border);cursor:pointer" data-conn="'+esc(c.name)+'" data-kind="'+esc(c.kind)+'" data-schema="'+esc(c.schema||'')+'">'+
          '<div style="font-weight:600;'+cell+'" title="'+esc(c.name)+'">'+esc(c.name)+'</div>'+
          '<div style="'+cell+'">'+esc(c.kind)+'</div>'+
          '<div style="color:var(--text3);'+cell+'" title="'+esc(c.target||'')+'">'+esc(c.target||'')+'</div>'+
          '<div>'+badge+'</div>'+
          '<div style="text-align:right"><button class="btn btn-xs btn-danger" data-del="'+esc(c.name)+'" data-dk="'+esc(c.kind)+'" title="Delete connection">Delete</button></div>'+
        '</div>';
      }).join('') +
      '</div>'+
      '<div style="font-size:10px;color:var(--text3);margin-top:6px">Click a row to browse its tables.</div>';
    for (let row of box.querySelectorAll('[data-conn]')){
      row.onclick = function(e){ if(e.target.closest('[data-del]')){ return; } dbConnBrowse(row.dataset.conn, row.dataset.kind, row.dataset.schema); };
    }
    for (let b of box.querySelectorAll('[data-del]')){
      b.onclick = function(e){ e.stopPropagation(); dbConnDelete(b.dataset.del, b.dataset.dk); };
    }
  };
  fetchT(dbBridgeUrl()+'/connections', {}, 8000).then(function(r){return r.json();})
    .then(function(j){ render((j&&j.connections)||[], true); })
    .catch(function(){ render([], false); });
}

function dbConnDelete(name, kind){
  if(kind==='demo'){ saveDemoConns(getDemoConns().filter(function(c){ return c.name!==name; })); dbConnRefreshList(); return; }
  fetch(dbBridgeUrl()+'/connections/'+encodeURIComponent(name), {method:'DELETE'})
    .then(function(){ dbConnRefreshList(); }).catch(function(){ dbConnRefreshList(); });
}

//  Browser (scoped to the active connection)
function dbConnBrowse(name, kind, schema){
  _activeConn = { name:name, kind:kind, schema:schema||'' };
  closeDbConn();
  document.getElementById('livedb-title').textContent = 'Browse — ' + name + (kind==='demo'?'  (demo: Fusion KB)':'');
  document.getElementById('livedb-owner').value = schema||'';
  document.getElementById('livedb-q').value = '';
  document.getElementById('livedb-detail').style.display = 'none';
  document.getElementById('livedb-modal').style.display = 'flex';
  liveDBSearch();
}
function closeLiveDB(){ document.getElementById('livedb-modal').style.display = 'none'; _liveDBTarget = null; }

function renderTableList(tables){
  var box = document.getElementById('livedb-results');
  if(!tables.length){ box.innerHTML='<div style="color:var(--text3);font-size:11px;padding:6px">No tables found.</div>'; return; }
  box.innerHTML = tables.map(function(t){
    var meta = (t.owner||'') + (t.numRows==null ? '' : '  &middot; ~'+t.numRows+' rows');
    return '<div class="livedb-row" data-o="'+(t.owner||'')+'" data-t="'+t.table+'">'+
      '<span style="font-weight:600">'+t.table+'</span><span style="color:var(--text3);font-size:10px">'+meta+'</span></div>';
  }).join('');
  for (let row of box.querySelectorAll('.livedb-row')){ row.onclick = function(){ liveDBPreview(row.dataset.o, row.dataset.t); }; }
}

var _liveDBSearchTimer = null;
function liveDBDebouncedSearch(){
  clearTimeout(_liveDBSearchTimer);
  _liveDBSearchTimer = setTimeout(liveDBSearch, 300);   // autosuggest ~300ms after typing stops
}
function liveDBSearch(){
  var box = document.getElementById('livedb-results');
  var owner = (document.getElementById('livedb-owner').value||'').trim();
  var q = (document.getElementById('livedb-q').value||'').trim();
  box.innerHTML = '<div style="color:var(--text3);font-size:11px;padding:6px">Searching…</div>';
  if(_activeConn.kind==='demo'){
    var qq = q.toUpperCase();
    var list = fusionTableNames().filter(function(t){ return !qq || t.includes(qq); }).slice(0,500)
                 .map(function(t){ return { owner:'DEMO', table:t, numRows:null }; });
    renderTableList(list); return;
  }
  var qs = ['conn='+encodeURIComponent(_activeConn.name)];
  if(owner) qs.push('owner='+encodeURIComponent(owner));
  if(q) qs.push('q='+encodeURIComponent(q));
  fetch(dbBridgeUrl()+'/tables?'+qs.join('&')).then(function(r){return r.json();}).then(function(j){
    if(!j || j.status!=='ok'){ box.innerHTML='<div style="color:#ef4444;font-size:11px;padding:6px">'+((j&&j.error)||'Error')+'</div>'; return; }
    renderTableList(j.tables);
  }).catch(function(){ box.innerHTML='<div style="color:#ef4444;font-size:11px;padding:6px">Cannot reach the bridge — is it running?</div>'; });
}

function renderColDetail(owner, table, cols){
  var box = document.getElementById('livedb-detail');
  var rows = cols.map(function(c){
    return '<tr><td>'+(c.pk?'🔑 ':'')+c.name+'</td><td style="color:var(--blue)">'+(c.dataType||'')+'</td>'+
           '<td style="text-align:center">'+(c.nullable?'Y':'N')+'</td><td style="color:var(--text3)">'+(c.comment||'')+'</td></tr>';
  }).join('');
  box.innerHTML =
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">'+
      '<span><b>'+((owner&&owner!=='DEMO')?owner+'.':'')+table+'</b> <span style="color:var(--text3);font-size:11px">'+cols.length+' columns</span></span>'+
      '<button class="btn-primary btn btn-sm" onclick="liveDBAddSource()">+ Add as Source Table</button>'+
    '</div>'+
    '<div style="max-height:260px;overflow:auto"><table class="livedb-tbl"><thead><tr>'+
      '<th>Column</th><th>Type</th><th style="text-align:center">Null?</th><th>Comment</th>'+
    '</tr></thead><tbody>'+rows+'</tbody></table></div>';
}

function liveDBPreview(owner, table){
  var box = document.getElementById('livedb-detail'); box.style.display='block';
  box.innerHTML = '<div style="color:var(--text3);font-size:11px">Loading columns for '+table+'…</div>';
  if(_activeConn.kind==='demo'){
    var cols = (fusionColsForTable(table)||[]).map(function(c){ return { name:c.name, dataType:c.dataType||'', nullable:true, pk:false, comment:null }; });
    _liveDBLast = { owner:owner, table:table, columns:cols };
    renderColDetail(owner, table, cols); return;
  }
  var qs = 'conn='+encodeURIComponent(_activeConn.name)+'&table='+encodeURIComponent(table)+((owner&&owner!=='DEMO')?'&owner='+encodeURIComponent(owner):'');
  fetch(dbBridgeUrl()+'/columns?'+qs).then(function(r){return r.json();}).then(function(j){
    if(!j || j.status!=='ok'){ box.innerHTML='<div style="color:#ef4444;font-size:11px">'+((j&&j.error)||'Error')+'</div>'; return; }
    _liveDBLast = { owner:owner, table:table, columns:j.columns };
    renderColDetail(owner, table, j.columns);
  }).catch(function(){ box.innerHTML='<div style="color:#ef4444;font-size:11px">Cannot load columns.</div>'; });
}

function liveDBAddSource(){
  if(!_liveDBLast) return;
  var owner = (_liveDBLast.owner && _liveDBLast.owner!=='DEMO') ? _liveDBLast.owner : '';
  var conn  = (_activeConn && _activeConn.kind!=='demo') ? _activeConn.name : '';
  var cols  = _liveDBLast.columns.map(function(c){ return { name:c.name, dataType:c.dataType }; });

  // Route the picked table into a subquery FROM member, if targeted.
  if (_liveDBTarget) {
    var tgt = _liveDBTarget; _liveDBTarget = null;
    var src = S.sources.find(function(s){ return s.id===tgt.srcId; });
    if (src) {
      if (tgt.kind === 'fromMember') {
        var ft = (src.derivedFromTables||[]).find(function(f){ return f.id===tgt.ftId; });
        if (ft) { ft.table = _liveDBLast.table; ft.schema = owner; ft.cols = cols; ft.colMode = ft.colMode||'all'; ft.dbConn = conn; ft.dbOwner = owner; }
      }
      closeLiveDB();
      refreshCard('sources'); refreshCard('joins'); refreshCard('filter'); refreshCard('mapping'); refreshSQL();
      notify('Loaded '+_liveDBLast.table+' ('+cols.length+' columns) into the subquery','ok');
      return;
    }
  }

  var s = newSource(S.sources.length+1);
  s.table   = _liveDBLast.table;
  s.schema  = owner;
  s.colMode = 'all';
  s.columns = cols;
  // Remember this came from a live DB so Auto-Load / Select All reload from the bridge,
  // NOT the Fusion KB (which doesn't contain live-DB tables).
  s.dbConn  = conn;
  s.dbOwner = owner;
  S.sources.push(s);
  if(S.sources.length===2){ S.joins.push(newJoin()); }
  closeLiveDB();
  refreshCard('sources'); refreshCard('joins'); refreshCard('filter'); refreshCard('mapping'); refreshSQL();
  notify('Added '+s.table+' with '+s.columns.length+' columns','ok');
}

// Reload a source's columns from the live DB bridge (used by Auto-Load / Select All for
// sources that came from a live connection). cb(true/false) fires when done.
function reloadSourceColsFromDB(src, cb){
  var owner = src.dbOwner || src.schema || '';
  var qs = 'conn='+encodeURIComponent(src.dbConn)+'&table='+encodeURIComponent(src.table)+
           (owner?'&owner='+encodeURIComponent(owner):'');
  fetchT(dbBridgeUrl()+'/columns?'+qs, {}, 40000).then(function(r){return r.json();}).then(function(j){
    if(j && j.status==='ok'){
      src.columns = j.columns.map(function(c){ return { name:c.name, dataType:c.dataType }; });
      if(cb) cb(true);
    } else {
      notify((j&&j.error) || 'Could not load columns from DB', 'err');
      if(cb) cb(false);
    }
  }).catch(function(){ notify('Cannot reach bridge to load columns.', 'err'); if(cb) cb(false); });
}

// Auto-Load Columns for a table picked via the "Live DB" module option (no dbConn yet).
// Parses OWNER.TABLE, then tries each saved live connection until one returns columns.
function autoLoadFromLiveDB(src, fullName, cb){
  var parts = String(fullName||'').split('.');
  var tbl = parts.pop();
  var owner = parts.join('.');
  fetchT(dbBridgeUrl()+'/connections', {}, 8000).then(function(r){return r.json();}).then(function(j){
    var conns = (j && j.connections) || [];
    if(!conns.length){ notify('No live DB connections. Connect one via Live DB first.','err'); if(cb) cb(false); return; }
    var done = false;
    var tryConn = function(i){
      if(done) return;
      if(i>=conns.length){ notify(fullName+' not found in any live DB connection.','err'); if(cb) cb(false); return; }
      var cn = conns[i];
      var qs = 'conn='+encodeURIComponent(cn.name)+'&table='+encodeURIComponent(tbl)+(owner?'&owner='+encodeURIComponent(owner):'');
      fetchT(dbBridgeUrl()+'/columns?'+qs, {}, 40000).then(function(r){return r.json();}).then(function(cj){
        if(done) return;
        if(cj && cj.status==='ok' && cj.columns && cj.columns.length){
          done = true;
          src.dbConn = cn.name; src.dbOwner = owner; src.table = tbl;
          if(owner) src.schema = owner;
          src.columns = cj.columns.map(function(c){ return { name:c.name, dataType:c.dataType }; });
          if(cb) cb(true);
        } else { tryConn(i+1); }
      }).catch(function(){ tryConn(i+1); });
    };
    tryConn(0);
  }).catch(function(){ notify('Cannot reach bridge to load columns.','err'); if(cb) cb(false); });
}

var _nlLastSQL = '';

function nlGenerate() {
  var txt = (document.getElementById('nl-input').value||'').trim();
  if (!txt) { document.getElementById('nl-input').focus(); return; }
  var parsed = nlDetect(txt);
  var sql = nlBuildSQL(parsed);
  _nlLastSQL = sql;
  document.getElementById('nl-out').innerHTML = hl(sql);
  var info = document.getElementById('nl-parse-info');
  var desc = nlDescribeParsed(parsed);
  if (desc) { info.innerHTML = desc; info.classList.add('show'); }
  else info.classList.remove('show');
  document.getElementById('nl-actions').style.display = 'flex';
}

// Common English words that show up in NL queries but are never real table names -
// filtered out so candidate-token extraction below doesn't waste bridge calls on them.
var NL_TABLE_STOPWORDS = ['give','show','get','find','list','fetch','select','from','where','the','and','for',
  'with','using','use','join','top','first','last','rows','row','columns','column','table','tables','all','any',
  'only','per','this','that','are','have','has','not','null','order','group','count','sum','avg','min','max',
  'filter','filters','data','value','values','please','need','want'];

// Pull out likely table-name tokens (e.g. BATCH_CONTROL) from the user's plain-English
// request, so nlGenerateAI can check whether they're real tables in a connected Live DB.
function nlExtractCandidateTables(txt){
  var tokens = (txt.match(/\b[A-Za-z][A-Za-z0-9_]{2,}\b/g) || []);
  var seen = {}, out = [];
  for (let t of tokens){
    if (NL_TABLE_STOPWORDS.indexOf(t.toLowerCase()) >= 0) continue;
    var up = t.toUpperCase();
    if (seen[up]) continue;
    seen[up] = true;
    out.push(up);
  }
  return out.slice(0, 6); // cap bridge round-trips
}

// Best-effort: ask each saved Live DB connection whether a candidate token is a real
// table, so AI Generate can ground Claude in the ACTUAL schema instead of guessing
// generic Oracle Fusion table/column names for tables it has never seen.
function nlLookupLiveTables(candidates){
  if (!candidates.length) return Promise.resolve([]);
  return fetchT(dbBridgeUrl()+'/connections', {}, 8000).then(function(r){return r.json();}).then(function(j){
    var conns = (j && j.connections) || [];
    if (!conns.length) return [];
    var found = [];
    var tryConn = function(cand, ci){
      if (ci >= conns.length) return Promise.resolve();
      var qs = 'conn='+encodeURIComponent(conns[ci].name)+'&table='+encodeURIComponent(cand);
      return fetchT(dbBridgeUrl()+'/columns?'+qs, {}, 8000).then(function(r){return r.json();}).then(function(cj){
        if (cj && cj.status==='ok' && cj.columns && cj.columns.length){
          found.push({ table:cand, columns:cj.columns.map(function(c){return c.name;}) });
          return;
        }
        return tryConn(cand, ci+1);
      }).catch(function(){ return tryConn(cand, ci+1); });
    };
    var tryCandidate = function(idx){
      if (idx >= candidates.length) return Promise.resolve();
      return tryConn(candidates[idx], 0).then(function(){ return tryCandidate(idx+1); });
    };
    return tryCandidate(0).then(function(){ return found; });
  }).catch(function(){ return []; });
}

async function nlGenerateAI() {
  if (aiIsDemo()) {
    // Demo mode: no real API call  run the offline engine and label the result.
    nlGenerate();
    if (_nlLastSQL) {
      _nlLastSQL = '-- [Demo mode] simulated with the offline engine  connect a real API key for Claude-powered results.\n' + _nlLastSQL;
      var o=document.getElementById('nl-out'); if(o) o.innerHTML = hl(_nlLastSQL);
      var a=document.getElementById('nl-actions'); if(a) a.style.display='flex';
    }
    notify('Demo mode: generated with the offline engine (not real Claude)','ok');
    return;
  }
  if (!S.apiKey || !S.apiKey.trim()) { notify('Connect an Anthropic API key first (top-right)  the offline "Generate SQL" works without it','err'); return; }
  var txt = (document.getElementById('nl-input').value||'').trim();
  if (!txt) return;
  var btn = document.getElementById('nl-ai-btn');
  btn.textContent = ' Generating'; btn.disabled = true;

  // Check the connected Live DB(s) for any table the user actually named, so the prompt
  // can be grounded in real table/column names instead of a generic Fusion-style guess.
  var liveTables = await nlLookupLiveTables(nlExtractCandidateTables(txt));
  var schemaBlock = liveTables.length
    ? 'Live database schema (these are REAL, verified tables from the user\'s connected database - use these exact table and column names):\n'+
      liveTables.map(function(t){ return '- '+t.table+'('+t.columns.join(', ')+')'; }).join('\n')+'\n\n'
    : '';

  var prompt = 'You are an Oracle SQL expert and ODI developer.\n'+
    schemaBlock+
    'Generate Oracle SQL (INSERT INTO...SELECT style or plain SELECT) for this request:\n"'+txt+'"\n\n'+
    'Rules:\n'+
    (liveTables.length
      ? '- Use the exact table and column names from the Live database schema above - do not invent or substitute other names.\n'
      : '- Use standard Oracle Fusion table names (AP_INVOICES_ALL, PER_ALL_PEOPLE_F, GL_JE_HEADERS, etc.) as a reasonable default since no matching live table was found.\n')+
    '- Use table aliases T1, T2, etc.\n'+
    '- For Oracle use FETCH FIRST N ROWS ONLY (not LIMIT)\n'+
    '- Add meaningful column aliases\n'+
    '- Include a -- comment explaining what the query does\n'+
    '- Return ONLY the SQL, no explanation text outside the SQL comment';

  var res = await callAI(prompt, 4000);
  btn.textContent = ' AI Generate'; btn.disabled = false;
  if (!res) return;
  // Strip markdown fences if present
  res = res.replaceAll(/```sql\s*/gi,'').replaceAll(/```\s*/g,'').trim();
  _nlLastSQL = res;
  document.getElementById('nl-out').innerHTML = hl(res);
  document.getElementById('nl-parse-info').classList.remove('show');
  document.getElementById('nl-actions').style.display = 'flex';
}

function nlCopySQL() {
  if (!_nlLastSQL) return;
  navigator.clipboard.writeText(_nlLastSQL).then(function(){ notify('SQL copied','ok'); });
}

// --- helpers extracted from nlLoadIntoBuilder (behavior-identical) ---
function nlLoadIntoBuilder_p1(parsed){
if (parsed.entities.length) {
    var ent = parsed.entities[0];
    var tbl = ent.tables[0];
    var src = S.sources[0];
    src.table = tbl; src.alias = 'T1';
    var fc = fusionColsForTable(tbl);
    src.columns = fc.length ? fc : src.columns;

    // Second entity as Source 2 with join
    if (parsed.entities.length > 1 || (parsed.wantDetail && ent.detailJoin)) {
      var tbl2 = parsed.entities.length > 1 ? parsed.entities[1].tables[0] : ent.detailJoin;
      if (S.sources.length < 2) S.sources.push(newSource(2));
      var src2 = S.sources[1];
      src2.table = tbl2; src2.alias = 'T2';
      var fc2 = fusionColsForTable(tbl2);
      src2.columns = fc2.length ? fc2 : src2.columns;

      // Auto-wire join
      var sug = fusionJoinSuggest(tbl, tbl2);
      if (sug.length && !S.joins.length) {
        S.joins = [{ id:uid(), type:'LEFT OUTER JOIN', rightId:src2.id, conds:[{l:'T1.'+sug[0].lc, op:'=', r:'T2.'+sug[0].rc}] }];
      }
    }
  }
}
function nlLoadIntoBuilder_p2(parsed){
if (parsed.groupByCols.length && parsed.agg) {
    S.groupBy = {
      dims: parsed.groupByCols.map(function(g,i){ return {id:uid(), col:'T1.'+g.col, alias:g.label}; }),
      aggs: [{ id:uid(), fn: parsed.agg.fn==='COUNT'&&!parsed.agg.col?'COUNT(*)':parsed.agg.fn,
               col: parsed.agg.col&&parsed.agg.col!=='*'?'T1.'+parsed.agg.col:'',
               val:'', alias:parsed.agg.fn+'_'+( parsed.agg.col||'TOTAL') }]
    };
  }
}
function nlLoadIntoBuilder_p3(parsed){
if (parsed.where.length) {
    S.filters = parsed.where.map(function(w){
      return { id:uid(), logic:'AND', srcId:S.sources[0].id, col:w.col, op:w.op, val:w.val };
    });
  }
}
function nlLoadIntoBuilder_p4(parsed){
if (parsed.orderBy.length) {
    S.orderBy = parsed.orderBy.map(function(o){ return { id:uid(), col:o.col, dir:o.dir, fn:'none', nulls:'' }; });
  }
}

function nlLoadIntoBuilder() {
  if (!_nlLastSQL) return;
  var txt = (document.getElementById('nl-input').value||'').trim();
  var parsed = nlDetect(txt);

  if (!parsed.entities.length && !(S.sources.length && S.sources[0].table)) {
    notify('Could not detect a table  type the table name explicitly','err'); return;
  }

  // Load first entity as Source 1
  nlLoadIntoBuilder_p1(parsed);

  // Group By
  nlLoadIntoBuilder_p2(parsed);

  // Filters  WHERE
  nlLoadIntoBuilder_p3(parsed);

  // Order By
  nlLoadIntoBuilder_p4(parsed);

  render();
  // Show the NL-generated SQL directly in the output panel
  // (render() regenerates from state, but mappings aren't populated yet so
  //  we override with the exact SQL the user just generated)
  var sqlOut = document.getElementById('sql-out');
  if (sqlOut && _nlLastSQL) sqlOut.innerHTML = hl(_nlLastSQL);
  closeNLModal();
  notify('Loaded into Builder  review and adjust as needed', 'ok');
}

function nlSetExample(txt) {
  document.getElementById('nl-input').value = txt;
  nlGenerate();
}
